import {
    Module,
    DynamicModule,
    Type,
} from "@nestjs/common"
import {
    ConfigurableModuleClass
} from "./bussiness.module-definition"
import {
    JobsModule
} from "./jobs"
import {
    OPTIONS_TYPE,
} from "./bussiness.module-definition"
import {
    TransactionsModule,
} from "./transactions"
import {
    BloomFiltersModule,
} from "./bloom-filters"
import {
    UserModule,
} from "./user"
import {
    ProgressModule,
} from "./progress"
import {
    FlashcardModule,
} from "./flashcard"
import {
    CodingModule,
} from "./coding"
import {
    DiscussionModule,
} from "./discussion"
import {
    NotificationModule,
} from "./notification"
import {
    ProjectionsModule,
} from "./projections"
import {
    LeagueModule,
} from "./league"
import {
    AchievementsModule,
} from "./achievements"
import {
    StreakModule,
} from "./streak"
import {
    InstallmentPlanModule,
} from "./installment-plan"
import {
    RewardsModule,
} from "./rewards"
import {
    DailyQuestModule,
} from "./daily-quest"
import {
    KpiRewardModule,
} from "./kpi-reward"
import {
    LearnerCmsModule,
} from "./learner-cms"
import {
    WeeklyChallengeModule,
} from "./weekly-challenge"
import {
    EsSyncModule,
} from "./es-sync"
import {
    LoyaltyModule,
} from "./loyalty"
import {
    CommunityModule,
} from "./community"
import {
    ChatModule,
} from "./chat"
import {
    ContentAiModule,
} from "./content-ai"
import {
    HeadhuntingsBussinessModule,
} from "./headhuntings"

@Module({
})
/**
 * The module for the bussiness logics.
 */
export class BussinessModule extends ConfigurableModuleClass {
    static register(options: typeof OPTIONS_TYPE): DynamicModule {
        const dynamicModule = super.register(options)
        const modules: Array<DynamicModule | Type<unknown>> = [
            // import the jobs module
            JobsModule.register(options),
            // import the transactions module
            TransactionsModule.register(options),
            // import the bloom filters module
            BloomFiltersModule.register(options),
            // import the user module
            UserModule.register(options),
            // import the progress module
            ProgressModule.register(options),
            // import the flashcard (interview-prep) module
            FlashcardModule.register(options),
            // import the coding-practice module
            CodingModule.register(options),
            // import the content discussion (comments + reactions) module
            DiscussionModule.register(options),
            // import the in-app notifications module
            NotificationModule.register(options),
            // import the CQRS projections module (progress + content + stats read-models)
            ProjectionsModule.register(options),
            // import the weekly-league module (tiers + cohorts + reset cron)
            LeagueModule.register(options),
            // import the achievements module (badge award engine)
            AchievementsModule.register(options),
            // import the streak-freeze module (buy + daily auto-protect cron)
            StreakModule.register(options),
            // import the installment-plan module (trß║ú g├│p ΓÇö plan lifecycle + daily enforcement cron)
            InstallmentPlanModule.register(options),
            // import the reward-store (Coin shop) module (catalog + wallet + redeem)
            RewardsModule.register(options),
            // import the daily-quest module (today's tasks + claim reward)
            DailyQuestModule.register(options),
            // import the kpi-reward module (weekly-KPI floor tracking + coin claim)
            KpiRewardModule.register(options),
            // import the learner self-management CMS reads (plain paginated lists)
            LearnerCmsModule.register(options),
            // import the weekly-challenge module (auto-rotate read-only event)
            WeeklyChallengeModule.register(options),
            // import the es-sync module (user ΓåÆ Elasticsearch `users` index sync)
            EsSyncModule.register(options),
            // import the loyalty-discount module (engagement-based course discount)
            LoyaltyModule.register(options),
            // import the community module (feed posts + comments + reactions)
            CommunityModule.register(options),
            // import the chat module (community room + founder DM threads)
            ChatModule.register(options),
            // import the content-AI module (grounded lesson Q&A, free model)
            ContentAiModule.register(options),
            // import the headhuntings module (CV-score gate on consultant contact details)
            HeadhuntingsBussinessModule.register(options),
        ]
        return {
            ...dynamicModule,
            imports: [
                ...modules,
            ],
            providers: [
                ...(dynamicModule.providers ?? []),
            ],
            exports: [
                ...modules,
            ],
        }
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
} from "typeorm"
import {
    CodingProblemEntity,
    CodingSolutionRevealEntity,
    CodingSubmissionEntity,
    CodingVerdict,
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases"
import {
    CodingProblemNotFoundException,
} from "@modules/exceptions"
import {
    WinstonLog,
    WinstonService,
} from "@modules/winston"
import {
    EnqueueJudgeCodingSubmissionJobService,
} from "../jobs"
import {
    DeviceService,
} from "../device"
import type {
    AcceptedSubmissionSummaryRow,
    AcceptedSubmissionSummaryResult,
    GetAcceptedSubmissionSummaryParams,
    ListMyCodingSubmissionsParams,
    ListMyCodingSubmissionsResult,
    RecordSolutionRevealParams,
    RecordSolutionRevealResult,
    SubmitCodingSolutionParams,
    SubmitCodingSolutionResult,
} from "./types"

/** Default page size for submission history. */
const DEFAULT_PAGE_SIZE = 20

@Injectable()
/**
 * Write-side + history business logic for coding submissions: persist a new
 * submission in `pending` state and enqueue the async judging job, and page a
 * user's submission history for a problem.
 */
export class CodingSubmissionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly enqueueJudgeCodingSubmissionJobService: EnqueueJudgeCodingSubmissionJobService,
        private readonly deviceService: DeviceService,
        private readonly winstonService: WinstonService,
    ) {}

    /**
     * Create a pending submission for the problem and enqueue its judging job.
     *
     * @param params - userId, problem slug, language, source
     * @returns the created submission id + the judging job id to subscribe to
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async submit({
        userId,
        slug,
        language,
        sourceCode,
        telemetry,
        ipAddress = null,
        userAgent = null,
        fingerprint = null,
    }: SubmitCodingSolutionParams): Promise<SubmitCodingSolutionResult> {
        // resolve the target problem (must exist and be enabled)
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
            })
        // unknown/disabled slug ΓåÆ typed not-found
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        // persist a fresh submission in the pending state (verdict set later by the worker)
        const submission = await this.entityManager.save(CodingSubmissionEntity,
            {
                user: {
                    id: userId,
                },
                problem: {
                    id: problem.id,
                },
                language,
                sourceCode,
                verdict: CodingVerdict.Pending,
                // request metadata captured for device tracking below
                ipAddress,
                userAgent,
                deviceFingerprint: fingerprint,
            })
        // best-effort: remember the device this submission came from. The
        // submission row already exists at this point, so a failure here
        // must be swallowed (logged, not thrown) ΓÇö otherwise it would strand
        // an already-persisted Pending submission with no judging job ever
        // enqueued for it.
        try {
            await this.deviceService.recordDevice({
                userId,
                fingerprint,
                ipAddress,
                userAgent,
            })
        } catch (error) {
            const cause = error instanceof Error ? error : new Error(String(error))
            this.winstonService.log(WinstonLog.BestEffortOperationFailed,
                {
                    op: "coding.device-record.failed",
                    userId,
                    referenceId: submission.id,
                    error: cause.message,
                })
        }
        // enqueue the async judging job; the returned job id is what the client subscribes to
        const job = await this.enqueueJudgeCodingSubmissionJobService.enqueue({
            userId,
            codingSubmissionId: submission.id,
        })
        // hand back both ids so the resolver can return them to the client
        return {
            submissionId: submission.id,
            jobId: job.id,
        }
    }

    /**
     * Record that the user revealed a problem's reference solution. Idempotent
     * (one row per user+problem). Once recorded, a later first solve of that
     * problem awards no points ΓÇö peeking the answer forfeits the score.
     *
     * @param params - the viewing user's id + the problem slug
     * @returns whether a new reveal row was created (false when already revealed)
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async recordSolutionReveal({
        userId,
        slug,
    }: RecordSolutionRevealParams): Promise<RecordSolutionRevealResult> {
        // resolve the target problem (must exist + be enabled) and load its reference
        // solutions ΓÇö this gated mutation is the ONLY place they are served to the client
        // (the problem detail read never carries them: not a GraphQL field, not indexed).
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
                relations: {
                    solutions: true,
                },
            })
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        const solutions = problem.solutions ?? []
        // already revealed ΓåÆ idempotent: skip re-recording but still serve the answer
        const existing = await this.entityManager.findOne(CodingSolutionRevealEntity,
            {
                where: {
                    user: {
                        id: userId,
                    },
                    problem: {
                        id: problem.id,
                    },
                },
            })
        if (existing) {
            return {
                revealed: false,
                solutions,
            }
        }
        // first reveal ΓåÆ persist the forfeit marker
        await this.entityManager.save(CodingSolutionRevealEntity,
            {
                user: {
                    id: userId,
                },
                problem: {
                    id: problem.id,
                },
            })
        return {
            revealed: true,
            solutions,
        }
    }

    /**
     * Page a user's submissions for one problem, newest first.
     *
     * @param params - userId, slug, pagination
     * @returns the page of submissions + total count
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async listMine({
        userId,
        slug,
        page = 1,
        limit = DEFAULT_PAGE_SIZE,
    }: ListMyCodingSubmissionsParams): Promise<ListMyCodingSubmissionsResult> {
        // resolve the problem id from the slug
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
            })
        // unknown/disabled slug ΓåÆ typed not-found
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        // page the user's submissions for this problem, newest first
        const [submissions,
            total] = await this.entityManager.findAndCount(
            CodingSubmissionEntity,
            {
                // filter by the RELATION properties, not the read-only @RelationId
                // virtual columns (`userId`/`codingProblemId` aren't queryable and
                // throw EntityPropertyNotFoundError).
                where: {
                    user: {
                        id: userId,
                    },
                    problem: {
                        id: problem.id,
                    },
                },
                order: {
                    createdAt: "DESC",
                },
                skip: (page - 1) * limit,
                take: limit,
            },
        )
        return {
            submissions,
            total,
        }
    }

    /**
     * Read a target user's accepted-submission summary for one problem ΓÇö the
     * language(s) used across ALL accepted attempts, plus the testcase counts
     * and first-solve time from the EARLIEST accepted attempt. Backs the
     * public profile's `userCodingProblemDetail` read; deliberately hand-rolled
     * (never returns a raw {@link CodingSubmissionEntity}) so `sourceCode` /
     * `perCaseResults` / reference solutions can never leak through it.
     *
     * @param params - {@link GetAcceptedSubmissionSummaryParams}
     * @returns the summary, or null when the target user has no accepted submission for the problem
     */
    async getAcceptedSummary(
        {
            userId,
            problemId,
        }: GetAcceptedSubmissionSummaryParams,
    ): Promise<AcceptedSubmissionSummaryResult | null> {
        const rows = await this.entityManager.query<Array<AcceptedSubmissionSummaryRow>>(
            `
            WITH accepted AS (
                SELECT language, passed_count, total_count, created_at
                FROM coding_submissions
                WHERE user_id = $1 AND coding_problem_id = $2 AND verdict = 'accepted'
            )
            SELECT
                (SELECT array_agg(DISTINCT language::text) FROM accepted) AS languages,
                (SELECT passed_count FROM accepted ORDER BY created_at ASC LIMIT 1) AS passed_count,
                (SELECT total_count FROM accepted ORDER BY created_at ASC LIMIT 1) AS total_count,
                (SELECT MIN(created_at) FROM accepted) AS first_solved_at
            `,
            [
                userId,
                problemId,
            ],
        )
        const row = rows[0]
        // no accepted attempt for this user+problem ΓåÆ nothing to show
        if (!row?.first_solved_at) {
            return null
        }
        return {
            languages: row.languages ?? [],
            verdict: CodingVerdict.Accepted,
            passedCount: Number(row.passed_count) || 0,
            totalCount: Number(row.total_count) || 0,
            firstSolvedAt: row.first_solved_at,
        }
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    IsNull,
} from "typeorm"
import {
    ContentCommentEntity,
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases"
import {
    envConfig,
} from "@modules/env"
import {
    CommentForbiddenException,
    CommentInvalidScopeException,
    CommentNotFoundException,
} from "@modules/exceptions"
import {
    EventEmitterService,
    EventName,
} from "@modules/event"
import type {
    CreateCommentParams,
    DeleteCommentParams,
    DeleteCommentResult,
    FounderAnsweredRow,
    ListCommentsParams,
    ListCommentsResult,
    ListCourseQuestionsParams,
    ListCourseQuestionsResult,
    ReplyCountRow,
    UpdateCommentParams,
} from "./types"
import {
    CourseQuestionFilter,
} from "./types"

/** Default page size for comment listings. */
const DEFAULT_LIMIT = 20

@Injectable()
/**
 * Domain service for threaded content comments: create/edit/soft-delete + paged listing.
 * Ownership is enforced here (never trust the client). Every mutation fans out a local
 * event so the Socket.IO gateway can push the change to subscribers of the content room.
 */
export class CommentService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly eventEmitterService: EventEmitterService,
    ) {}

    /**
     * Loads a comment with its author, or throws if it does not exist.
     * @param commentId - Comment primary id.
     * @returns The comment entity with `user` relation loaded.
     */
    async getCommentOrThrow(commentId: string): Promise<ContentCommentEntity> {
        // load the row with author so callers can build a node + check ownership
        const comment = await this.entityManager.findOne(ContentCommentEntity,
            {
                where: {
                    id: commentId,
                },
                relations: {
                    user: true,
                },
            })
        // a missing row is a hard 404-style failure for every caller
        if (!comment) {
            throw new CommentNotFoundException({
                commentId,
            })
        }
        return comment
    }

    /**
     * Creates a top-level comment or a reply. A top-level comment must be scoped to
     * exactly one of `contentId` (a lesson question) or `courseId` (a course-general
     * "hß╗Åi chung kh├│a" question) ΓÇö see {@link CreateCommentParams}. A reply always
     * inherits its scope from the parent (the caller's own scope fields are ignored
     * for a reply, so a reply can never be spoofed into a different scope).
     * @param params - {@link CreateCommentParams}
     * @returns The persisted comment (author relation loaded).
     */
    async createComment({
        contentId,
        courseId,
        parentCommentId,
        body,
        user,
    }: CreateCommentParams): Promise<ContentCommentEntity> {
        // resolved scope for the row about to be created
        let resolvedContentId = contentId ?? null
        let resolvedCourseId = courseId ?? null
        if (parentCommentId) {
            // when replying, make sure the parent really exists, then inherit its scope
            const parent = await this.getCommentOrThrow(parentCommentId)
            resolvedContentId = parent.contentId
            resolvedCourseId = parent.courseId
        } else if (Boolean(resolvedContentId) === Boolean(resolvedCourseId)) {
            // a top-level comment must set EXACTLY one of content/course (never both, never neither)
            throw new CommentInvalidScopeException({
                contentId: resolvedContentId,
                courseId: resolvedCourseId,
            })
        }
        // build the row via relation ids only ΓÇö no need to load full content/course/user rows
        const draft = this.entityManager.create(ContentCommentEntity,
            {
                body,
                isDeleted: false,
                editedAt: null,
                content: resolvedContentId ? {
                    id: resolvedContentId,
                } : null,
                course: resolvedCourseId ? {
                    id: resolvedCourseId,
                } : null,
                user: {
                    id: user.id,
                },
                // null parent marks a top-level comment
                parentComment: parentCommentId ? {
                    id: parentCommentId,
                } : null,
            })
        // persist then reload so RelationId virtual columns + author are populated for the node
        const saved = await this.entityManager.save(draft)
        const comment = await this.getCommentOrThrow(saved.id)
        // a course-general question has no per-lesson room to broadcast into ΓÇö only
        // per-lesson comments push a realtime update to viewers of that content
        if (resolvedContentId) {
            await this.eventEmitterService.emit({
                event: EventName.CommentCreated,
                payload: {
                    contentId: resolvedContentId,
                    commentId: comment.id,
                    parentCommentId: comment.parentCommentId,
                },
            })
        }
        return comment
    }

    /**
     * Edits a comment's body. Only the author may edit.
     * @param params - {@link UpdateCommentParams}
     * @returns The updated comment (author relation loaded).
     */
    async updateComment({
        commentId,
        body,
        user,
    }: UpdateCommentParams): Promise<ContentCommentEntity> {
        // load + ownership guard before mutating anything
        const comment = await this.getCommentOrThrow(commentId)
        // reject edits from anyone who is not the author
        if (comment.userId !== user.id) {
            throw new CommentForbiddenException({
                commentId,
                userId: user.id,
            })
        }
        // apply the new body and stamp the edit time so the UI can show "(edited)"
        comment.body = body
        comment.editedAt = new Date()
        await this.entityManager.save(comment)
        // fan out so subscribers refetch the edited comment ΓÇö only a per-lesson comment
        // has a content room to target; a course-general question has none (its roll-up
        // page re-fetches via normal query, no realtime push needed there).
        if (comment.contentId) {
            await this.eventEmitterService.emit({
                event: EventName.CommentUpdated,
                payload: {
                    contentId: comment.contentId,
                    commentId: comment.id,
                    parentCommentId: comment.parentCommentId,
                },
            })
        }
        return comment
    }

    /**
     * Soft-deletes a comment (keeps the row + replies). Only the author may delete.
     * @param params - {@link DeleteCommentParams}
     * @returns The deleted comment id.
     */
    async softDeleteComment({
        commentId,
        user,
    }: DeleteCommentParams): Promise<DeleteCommentResult> {
        // load + ownership guard
        const comment = await this.getCommentOrThrow(commentId)
        // reject deletes from anyone who is not the author
        if (comment.userId !== user.id) {
            throw new CommentForbiddenException({
                commentId,
                userId: user.id,
            })
        }
        // flag as deleted instead of removing so child replies + thread shape survive
        comment.isDeleted = true
        await this.entityManager.save(comment)
        // notify the room so clients swap the body for a "[deleted]" placeholder ΓÇö
        // course-general questions have no content room (see updateComment above).
        if (comment.contentId) {
            await this.eventEmitterService.emit({
                event: EventName.CommentDeleted,
                payload: {
                    contentId: comment.contentId,
                    commentId: comment.id,
                    parentCommentId: comment.parentCommentId,
                },
            })
        }
        return {
            id: comment.id,
        }
    }

    /**
     * Lists comments ΓÇö top-level comments of a lesson/course scope by default, or one
     * parent's replies when `parentCommentId` is provided. Paged (1-based).
     *
     * A reply listing is scoped by `parentCommentId` ALONE ΓÇö the parent already pins the
     * exact thread, so no separate content/course match is needed (and a course-general
     * question's replies have no `contentId` to match against anyway). A top-level listing
     * requires exactly one of `contentId`/`courseId`.
     * @param params - {@link ListCommentsParams}
     * @returns The page of comments + total count.
     */
    async listComments({
        contentId,
        courseId,
        parentCommentId,
        page = 1,
        limit = DEFAULT_LIMIT,
    }: ListCommentsParams): Promise<ListCommentsResult> {
        // translate 1-based page into an offset; clamp to non-negative
        const skip = Math.max(0,
            page - 1) * limit
        // a top-level listing must pin EXACTLY one scope ΓÇö an unscoped `where` would
        // silently match every comment across every content/course (TypeORM ignores
        // `undefined` conditions), so guard against a caller omitting both
        if (!parentCommentId && Boolean(contentId) === Boolean(courseId)) {
            throw new CommentInvalidScopeException({
                contentId: contentId ?? null,
                courseId: courseId ?? null,
            })
        }
        // replies: scoped by parent alone; top-level: scoped by content OR course
        const where = parentCommentId
            ? {
                parentComment: {
                    id: parentCommentId,
                },
            }
            : {
                content: contentId ? {
                    id: contentId,
                } : undefined,
                course: courseId ? {
                    id: courseId,
                } : undefined,
                parentComment: IsNull(),
            }
        const [comments,
            total] = await this.entityManager.findAndCount(ContentCommentEntity,
            {
                where,
                relations: {
                    user: true,
                },
                // chronological order keeps a thread readable top-to-bottom
                order: {
                    createdAt: "ASC",
                },
                skip,
                take: limit,
            })
        return {
            comments,
            total,
        }
    }

    /**
     * Counts direct replies for a set of comments in one grouped query (avoids N+1).
     * @param commentIds - Parent comment ids to count replies for.
     * @returns Map of comment id ΓåÆ direct reply count (missing key = 0).
     */
    async countReplies(commentIds: Array<string>): Promise<Record<string, number>> {
        // nothing to count ΓåÆ cheap exit, also avoids an empty IN () clause
        if (commentIds.length === 0) {
            return {
            }
        }
        // one grouped COUNT keyed by parent id rather than a query per comment
        const rows = await this.entityManager
            .createQueryBuilder(ContentCommentEntity,
                "comment")
            .select("comment.parent_comment_id",
                "parentId")
            .addSelect("COUNT(*)",
                "count")
            .where("comment.parent_comment_id IN (:...commentIds)",
                {
                    commentIds,
                })
            .groupBy("comment.parent_comment_id")
            .getRawMany<ReplyCountRow>()
        // fold the raw rows into a lookup the resolver can index per comment
        return rows.reduce<Record<string, number>>((acc, row) => {
            acc[row.parentId] = Number(row.count)
            return acc
        },
        {
        })
    }

    /**
     * Returns the set of question ids (from the given ids) that have at least one
     * reply authored by the founder ΓÇö used to flag "officially answered" questions.
     * @param questionIds - Top-level comment ids to test for a founder reply.
     * @returns A set of the ids that have a founder reply (subset of the input).
     */
    async findFounderAnswered(questionIds: Array<string>): Promise<Set<string>> {
        // empty input ΓåÆ nothing to test; also avoids an invalid empty IN () clause
        if (questionIds.length === 0) {
            return new Set<string>()
        }
        // the founder username is env-driven so it can differ per deployment
        const founderUsername = envConfig().community.founderUsername
        // distinct parent ids among replies whose author is the founder
        const rows = await this.entityManager
            .createQueryBuilder(ContentCommentEntity,
                "reply")
            // join the reply author to filter by their username
            .innerJoin("reply.user",
                "author")
            .select("DISTINCT reply.parent_comment_id",
                "parentId")
            // only replies of the questions on this page, authored by the founder
            .where("reply.parent_comment_id IN (:...questionIds)",
                {
                    questionIds,
                })
            .andWhere("author.username = :founderUsername",
                {
                    founderUsername,
                })
            // exclude soft-deleted replies so a removed founder answer does not count
            .andWhere("reply.is_deleted = false")
            .getRawMany<FounderAnsweredRow>()
        // fold the flat rows into a fast membership set for the mapper
        return new Set(rows.map((row) => row.parentId))
    }

    /**
     * Lists a course's questions: top-level, non-deleted comments across ALL lessons
     * of the course, with answer aggregates. The answered/unanswered filter is folded
     * into the WHERE via an EXISTS subquery so pagination + `total` reflect the filter.
     * @param params - {@link ListCourseQuestionsParams}
     * @returns The page of question rows (each carrying reply count + founder-answer flag) + total.
     */
    async listCourseQuestions({
        courseId,
        filter,
        search,
        page = 1,
        limit = DEFAULT_LIMIT,
        userId,
    }: ListCourseQuestionsParams): Promise<ListCourseQuestionsResult> {
        // translate 1-based page into a row offset; clamp to non-negative
        const skip = Math.max(0,
            page - 1) * limit
        // base query: top-level comments in this course ΓÇö either a per-lesson question
        // (content ΓåÆ module ΓåÆ course) OR a course-general question (comment.course_id
        // set directly, no content). LEFT joins so a course-general row's null content
        // does not exclude it; the WHERE below accepts EITHER path.
        const queryBuilder = this.entityManager
            .createQueryBuilder(ContentCommentEntity,
                "comment")
            .leftJoin("comment.content",
                "content")
            .leftJoin("content.module",
                "module")
            .leftJoin("module.course",
                "lessonCourse")
            // load the content (title + module id) and author for the node mapping
            .leftJoinAndSelect("comment.content",
                "contentSelected")
            .leftJoinAndSelect("contentSelected.module",
                "moduleSelected")
            .leftJoinAndSelect("comment.user",
                "user")
            // scope: this course, via either path
            .where(
                "(lessonCourse.id = :courseId OR comment.course_id = :courseId)",
                {
                    courseId,
                },
            )
            // a "question" is a top-level (non-reply), non-deleted comment
            .andWhere("comment.parent_comment_id IS NULL")
            .andWhere("comment.is_deleted = false")
        // optional case-insensitive body match; trim to ignore blank search
        const trimmedSearch = search?.trim()
        if (trimmedSearch) {
            // ILIKE with wildcards for a substring match, parameterised to stay safe
            queryBuilder.andWhere("comment.body ILIKE :search",
                {
                    search: `%${trimmedSearch}%`,
                })
        }
        // `mine` ΓåÆ restrict to questions the caller authored
        if (filter === CourseQuestionFilter.Mine) {
            queryBuilder.andWhere("comment.user_id = :userId",
                {
                    userId,
                })
        }
        // answered/unanswered folded into WHERE via EXISTS so `total` matches the filter.
        // a reply = a non-deleted comment whose parent is this question.
        if (filter === CourseQuestionFilter.Unanswered) {
            // no non-deleted reply exists ΓåÆ still in the answering queue
            queryBuilder.andWhere(
                "NOT EXISTS (SELECT 1 FROM content_comments reply WHERE reply.parent_comment_id = comment.id AND reply.is_deleted = false)",
            )
        } else if (filter === CourseQuestionFilter.Answered) {
            // at least one non-deleted reply exists ΓåÆ already answered
            queryBuilder.andWhere(
                "EXISTS (SELECT 1 FROM content_comments reply WHERE reply.parent_comment_id = comment.id AND reply.is_deleted = false)",
            )
        }
        // ordering: unanswered surfaces the oldest first (a FIFO answering queue);
        // every other view shows the newest question first
        queryBuilder.orderBy("comment.created_at",
            filter === CourseQuestionFilter.Unanswered ? "ASC" : "DESC")
        // apply pagination window and run count + rows in one round-trip
        const [comments,
            total] = await queryBuilder
            .skip(skip)
            .take(limit)
            .getManyAndCount()
        // collect the page's question ids once to batch the two aggregate lookups
        const questionIds = comments.map((comment) => comment.id)
        // reply (answer) counts per question, and the founder-answered membership set
        const replyCounts = await this.countReplies(questionIds)
        const founderAnswered = await this.findFounderAnswered(questionIds)
        // assemble rows: entity + computed aggregates the resolver maps into nodes
        const questions = comments.map((comment) => ({
            comment,
            // missing key in the grouped count means zero replies
            replyCount: replyCounts[comment.id] ?? 0,
            // membership in the set means an official (founder) answer exists
            answeredByFounder: founderAnswered.has(comment.id),
        }))
        return {
            questions,
            total,
        }
    }
}

import type {
    ContentCommentEntity,
    UserEntity,
} from "@modules/databases"

/**
 * Params to create a comment (top-level or reply). A top-level comment is scoped to
 * EITHER a lesson content ({@link contentId}) or a whole course ({@link courseId}, a
 * "hß╗Åi chung kh├│a" course-general question) ΓÇö exactly one must be set. A reply
 * (`parentCommentId` set) inherits its scope from the parent instead; both scope
 * fields are ignored for replies.
 */
export interface CreateCommentParams {
    /** Content the comment is attached to; omit for a course-general question. */
    contentId?: string | null
    /** Course the comment is attached to (course-general question); omit for a lesson question. */
    courseId?: string | null
    /** Parent comment id when replying; null/omitted for a top-level comment. */
    parentCommentId?: string | null
    /** Raw comment body authored by the user. */
    body: string
    /** Authenticated author. */
    user: UserEntity
}

/** Params to edit an existing comment (author only). */
export interface UpdateCommentParams {
    /** Comment being edited. */
    commentId: string
    /** New body to persist. */
    body: string
    /** Authenticated user performing the edit (must be the author). */
    user: UserEntity
}

/** Params to soft-delete a comment (author only). */
export interface DeleteCommentParams {
    /** Comment being deleted. */
    commentId: string
    /** Authenticated user performing the delete (must be the author). */
    user: UserEntity
}

/** Result of a soft-delete. */
export interface DeleteCommentResult {
    /** Id of the deleted comment. */
    id: string
}

/**
 * Params to list comments, optionally scoped to one parent (replies). A top-level
 * listing (`parentCommentId` omitted) requires exactly one of `contentId`/`courseId`;
 * a reply listing only needs `parentCommentId` ΓÇö it ignores both scope fields (the
 * parent already pins the exact thread, and a course-general question's replies have
 * no `contentId` to scope by anyway).
 */
export interface ListCommentsParams {
    /** Content whose top-level comments are listed; omit for a course-general scope or a reply listing. */
    contentId?: string | null
    /** Course whose top-level (course-general) comments are listed; omit for a lesson scope or a reply listing. */
    courseId?: string | null
    /** When set, list replies of this comment; when null/omitted, list top-level comments. */
    parentCommentId?: string | null
    /** 1-based page number (default 1). */
    page?: number
    /** Page size (default 20). */
    limit?: number
}

/**
 * One raw grouped-count row from the reply-count query
 * (`SELECT parent_comment_id AS parentId, COUNT(*) AS count`). `count` is a
 * string because Postgres returns `COUNT(*)` as `bigint` text over the wire.
 */
export interface ReplyCountRow {
    /** The parent comment whose replies were counted. */
    parentId: string
    /** Number of direct replies, as a numeric string. */
    count: string
}

/** Result of a comment list query. */
export interface ListCommentsResult {
    /** The page of comment rows (author relation loaded). */
    comments: Array<ContentCommentEntity>
    /** Total comments matching the scope (for pagination). */
    total: number
}

/**
 * Answer-status filter for the course Q&A roll-up. A "question" is a top-level
 * content comment; its "answers" are its replies. This drives the WHERE/order of
 * {@link ListCourseQuestionsParams}.
 */
export enum CourseQuestionFilter {
    /** Questions with zero replies yet (the answering queue). */
    Unanswered = "unanswered",
    /** Questions that already have at least one reply. */
    Answered = "answered",
    /** Questions authored by the calling user. */
    Mine = "mine",
    /** No answer-status filter ΓÇö every question in the course. */
    All = "all",
}

/**
 * Params to list a course's questions (top-level comments across all its lessons).
 */
export interface ListCourseQuestionsParams {
    /** Course whose lessons' top-level comments are aggregated. */
    courseId: string
    /** Answer-status filter applied to the roll-up. */
    filter: CourseQuestionFilter
    /** Optional case-insensitive body substring to match (ILIKE). */
    search?: string | null
    /** 1-based page number (default 1). */
    page?: number
    /** Page size (default 20). */
    limit?: number
    /** Calling user id ΓÇö required to resolve the `mine` filter. */
    userId: string
}

/**
 * One question row: the top-level comment entity plus the computed answer
 * aggregates the resolver needs to build a client node. The comment carries its
 * `content` (ΓåÆ `module`) and `user` relations loaded.
 */
export interface CourseQuestionRow {
    /** The top-level comment entity (with `content.module` + `user` loaded). */
    comment: ContentCommentEntity
    /** Number of direct replies (answers) to this question. */
    replyCount: number
    /** Whether any reply's author is the founder (an official answer). */
    answeredByFounder: boolean
}

/** Result of the course questions roll-up query. */
export interface ListCourseQuestionsResult {
    /** The page of question rows with their computed answer aggregates. */
    questions: Array<CourseQuestionRow>
    /** Total questions matching the filter (for pagination). */
    total: number
}

/**
 * One raw grouped-count row from the founder-answered lookup
 * (`SELECT parent_comment_id AS parentId`). Only the parent id is selected ΓÇö
 * presence in the set means "answered by founder".
 */
export interface FounderAnsweredRow {
    /** The parent (question) comment id that has a founder reply. */
    parentId: string
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    MoreThanOrEqual,
    Not,
} from "typeorm"
import {
    FlashcardDueReviewSessionEntity,
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases"
import {
    UserService,
} from "../user"
import type {
    CompleteFlashcardDueReviewSessionParams,
    CompleteFlashcardDueReviewSessionResult,
    FindFlashcardDueReviewSessionByIdParams,
    FindMyInProgressFlashcardDueReviewSessionParams,
    MyInProgressFlashcardDueReviewSessionResultData,
    StartFlashcardDueReviewSessionParams,
    StartFlashcardDueReviewSessionResult,
    SyncFlashcardDueReviewSessionProgressParams,
    SyncFlashcardDueReviewSessionProgressResult,
} from "./types/flashcard-due-review-session"

/**
 * How far back a session's last sync may be for it to still be offered as
 * resumable ΓÇö same reasoning as `FlashcardReviewSessionService`'s own
 * `RESUME_WINDOW_HOURS`: a session synced longer ago than this is treated as
 * effectively abandoned even though `startFlashcardDueReviewSession` has not
 * yet flipped its status (that only happens when the SAME enrollment starts a
 * NEW draw).
 */
const RESUME_WINDOW_HOURS = 24

@Injectable()
/**
 * Business logic for the resumable CROSS-DECK due-review batch ("DueReview")
 * session ΓÇö mirrors
 * {@link import("./flashcard-review-session.service").FlashcardReviewSessionService}'s
 * resumable-draw shape, but scoped to an ENROLLMENT only (no deck): a
 * due-review batch draws cards across MULTIPLE decks in one course, so it
 * cannot reuse the deck-scoped review-session table/service. The actual SM-2
 * grading still happens per-card through the existing `reviewFlashcard`
 * mutation ({@link import("./flashcard-review.service").FlashcardReviewService.review});
 * this service is purely a resumable progress/bookkeeping wrapper around a
 * sequence of those calls, mirroring `FlashcardReviewSessionService`'s own XP
 * DECISION: `reviewFlashcard` grants no XP today, so `xpEarned` on
 * `flashcard_due_review_sessions` is a CLIENT-REPORTED BOOKKEEPING SNAPSHOT
 * ONLY ΓÇö `sync`/`complete` below persist whatever value the caller sends,
 * with NO `xp_histories` insert, NO `XpSource` addition, and NO daily-cap
 * logic.
 */
export class FlashcardDueReviewSessionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly userService: UserService,
    ) {}

    /**
     * Persist ONE resumable due-review batch draw over a course, retiring any
     * PRIOR "in_progress" draw for the same enrollment first so a learner
     * never has two resumable due-review batches at once ΓÇö mirrors
     * `FlashcardReviewSessionService.start`'s own "abandon prior in_progress
     * row" step (there further scoped by deck; here scoped by enrollment
     * alone, since a due-review batch spans multiple decks).
     *
     * @param params - {@link StartFlashcardDueReviewSessionParams}
     * @returns the newly-persisted session's id.
     */
    async start(
        {
            userId,
            courseId,
            cardIds,
        }: StartFlashcardDueReviewSessionParams,
    ): Promise<StartFlashcardDueReviewSessionResult> {
        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            courseId,
        )

        // retire the enrollment's previous in-flight draw (if any) BEFORE
        // persisting the new one, so resume-lookup never has two candidates.
        await this.entityManager.update(
            FlashcardDueReviewSessionEntity,
            {
                enrollment: {
                    id: enrollment.id,
                },
                status: "in_progress",
            },
            {
                status: "abandoned",
            },
        )

        const session = await this.entityManager.save(
            FlashcardDueReviewSessionEntity,
            {
                enrollment,
                cardIds,
                currentIndex: 0,
                reviewedCount: 0,
                gradedIndexes: [],
                xpEarned: 0,
                status: "in_progress",
            },
        )

        return {
            sessionId: session.id,
        }
    }

    /**
     * Sync an in-flight due-review batch session's position + progress ΓÇö
     * ownership-scoped, silently no-ops (never throws) for a session that is
     * not found/owned or no longer "in_progress", same reasoning as
     * `FlashcardReviewSessionService.sync` (a background periodic sync must
     * never surface an error toast mid-batch).
     *
     * @param params - {@link SyncFlashcardDueReviewSessionProgressParams}
     * @returns whether the sync was applied.
     */
    async sync(
        {
            userId,
            sessionId,
            currentIndex,
            reviewedCount,
            gradedIndexes,
            xpEarned,
        }: SyncFlashcardDueReviewSessionProgressParams,
    ): Promise<SyncFlashcardDueReviewSessionProgressResult> {
        const session = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                    status: true,
                },
            },
        )

        if (!session || session.status !== "in_progress") {
            return {
                success: false,
            }
        }

        await this.entityManager.update(
            FlashcardDueReviewSessionEntity,
            {
                id: session.id,
            },
            {
                currentIndex,
                reviewedCount,
                // only overwrite the graded-index set when the caller sent one
                // ΓÇö omitting it must leave the column untouched (same tolerance
                // the rest of the sync payload has), not wipe it to undefined.
                ...(gradedIndexes !== undefined ? {
                    gradedIndexes,
                } : {
                }),
                xpEarned,
            },
        )

        return {
            success: true,
        }
    }

    /**
     * Record a finished due-review batch session ΓÇö flips the row to
     * "completed" and snapshots the final reviewed-count/xpEarned the caller
     * reports. Ownership-scoped via `status: Not("completed")` (loosened
     * 2026-07-12 ΓÇö was `status: "in_progress"`, mirroring
     * `FlashcardReviewSessionService.complete`'s own guard): the STRICT
     * `"in_progress"` match silently updated ZERO rows (TypeORM `update()`
     * never throws on a no-match) whenever the row had ALREADY been raced to
     * "abandoned" by a concurrent `start()` (retires every prior in_progress
     * row for the enrollment ΓÇö e.g. a duplicate resolve-or-start effect fire)
     * BEFORE this call landed ΓÇö the FE still reported "success" (the mutation
     * itself never errored), but the row was permanently stuck un-completed,
     * so a later revisit-by-URL/resume kept re-entering the review instead of
     * showing the recap (thß║ºy 2026-07-12: "sao c├│ kß║┐t quß║ú phi├¬n ├┤n rß╗ôi m├á F5
     * lß║íi ra flashcard cuß╗æi"). `Not("completed")` still refuses to re-flip an
     * ALREADY-completed row (replay-safe, same as before) while tolerating
     * "abandoned" ΓÇö the learner genuinely finished, so their completion
     * should win regardless of what else raced the row's status meanwhile.
     *
     * NO XP is granted here ΓÇö see the class doc's XP DECISION. `xpEarned` is
     * echoed straight through as a bookkeeping snapshot, never written to
     * `xp_histories`.
     *
     * @param params - {@link CompleteFlashcardDueReviewSessionParams}
     * @returns the reviewed-count/xpEarned snapshotted onto the row.
     */
    async complete(
        {
            userId,
            sessionId,
            reviewedCount,
            xpEarned,
        }: CompleteFlashcardDueReviewSessionParams,
    ): Promise<CompleteFlashcardDueReviewSessionResult> {
        // Ownership is a two-level nested relation (enrollment ΓåÆ user), which a
        // bare `update()` cannot express: TypeORM compiles `update` to an
        // UpdateQueryBuilder that has no JOINs, so a nested-relation WHERE throws
        // "Cannot find alias for relation". Resolve ownership with a `findOne`
        // (which CAN join) first, then update by the scalar `id` + the
        // replay-safe `status` guard ΓÇö mirroring `sync()` in this same service.
        const owned = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                },
            },
        )
        if (owned) {
            await this.entityManager.update(
                FlashcardDueReviewSessionEntity,
                {
                    id: sessionId,
                    status: Not("completed"),
                },
                {
                    status: "completed",
                    reviewedCount,
                    xpEarned,
                },
            )
        }

        return {
            reviewedCount,
            xpEarned,
        }
    }

    /**
     * Find the most recent `status = "in_progress"` due-review batch session,
     * synced within {@link RESUME_WINDOW_HOURS}, for the caller's enrollment
     * in one course ΓÇö mirrors
     * `MyInProgressFlashcardQuizSessionService.find`/
     * `FlashcardReviewSessionService.findInProgress`, scoped by course
     * (course-wide, like quiz sessions ΓÇö NOT per-deck, unlike review
     * sessions).
     *
     * @param params - {@link FindMyInProgressFlashcardDueReviewSessionParams}
     * @returns the resumable session, or null when there is none.
     */
    async findInProgress(
        {
            userId,
            courseId,
        }: FindMyInProgressFlashcardDueReviewSessionParams,
    ): Promise<MyInProgressFlashcardDueReviewSessionResultData | null> {
        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            courseId,
        )

        const resumeWindowStart = new Date(
            Date.now() - RESUME_WINDOW_HOURS * 60 * 60 * 1000,
        )

        const session = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    enrollment: {
                        id: enrollment.id,
                    },
                    status: "in_progress",
                    updatedAt: MoreThanOrEqual(resumeWindowStart),
                },
                order: {
                    updatedAt: "DESC",
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }

    /**
     * Find a due-review batch session directly by its id (ownership-checked
     * against the caller) ΓÇö mirrors
     * `FlashcardReviewSessionService.findById`; no deck identity to attach
     * here (a due-review batch spans multiple decks, per-card deckId comes
     * from the drawn cards themselves, not the session row). NOT
     * window/status-scoped like `findInProgress` ΓÇö a direct link to a
     * completed/abandoned session still resolves.
     *
     * @param params - {@link FindFlashcardDueReviewSessionByIdParams}
     * @returns the session, or null when not found/not owned by the caller.
     */
    async findById(
        {
            userId,
            sessionId,
        }: FindFlashcardDueReviewSessionByIdParams,
    ): Promise<MyInProgressFlashcardDueReviewSessionResultData | null> {
        const session = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    In,
    Not,
} from "typeorm"
import {
    ContentEntity,
    FlashcardCardEntity,
    FlashcardQuizSessionEntity,
    InjectPrimaryPostgreSQLEntityManager,
    XpHistoryEntity,
    XpSource,
} from "@modules/databases"
import {
    CourseRagRetrievalService,
} from "@modules/rag"
import {
    FLAT_POINTS,
    writeXpHistory,
} from "@features/api/processors/ai/shared/xp"
import {
    JOB_READINESS_BUILDING_THRESHOLD,
} from "@features/api/core/graphql/queries/users/job-readiness/constants"
import {
    UserFlashcardStatsProjectionService,
} from "../projections/user-flashcard-stats"
import type {
    CompleteFlashcardQuizSessionParams,
    CompleteFlashcardQuizSessionResult,
    QuizSessionAnswerParams,
    QuizSessionWeakTagResult,
    QuizXpSumRow,
} from "./types"

/** XP awarded per answered card, before the coverage weighting is applied. */
const PER_CARD_XP = 3

/** Hard ceiling on the XP a single quick-quiz session can ever grant. */
const MAX_XP_PER_SESSION = 15

/** Upper bound on cards counted toward the reward (guards against inflated inputs). */
const MAX_ANSWERED_CARDS = 10

/**
 * Hard ceiling on the XP `FlashcardQuiz` can grant a (user, course) pair per VN
 * calendar day ΓÇö four sessions' worth of {@link MAX_XP_PER_SESSION}. Without
 * this, the only limiter was the per-session ceiling, so an unlimited number
 * of sessions per day could farm the leaderboard without ever really studying.
 */
const DAILY_QUIZ_XP_CAP = 60

/** IANA timezone the daily cap's calendar day is measured in (VN local day, matches the daily-quest convention). */
const DAILY_CAP_TIMEZONE = "Asia/Ho_Chi_Minh"

/** Upper bound on weak tags returned per session (top-N weakest, not a silent drop of the rest). */
const MAX_WEAK_TAGS = 5

@Injectable()
/**
 * Business logic for the flashcard quick-quiz ("Hß╗Åi nhanh") flow. Finishing a
 * session grants a capped, coverage-weighted XP reward written as a single
 * `xp_histories` row via {@link writeXpHistory} ΓÇö which in turn feeds the streak,
 * weekly XP, and per-course leaderboard (all read from `xp_histories`). The grant
 * is idempotent on the client-generated session id so a replayed "complete" call
 * never double-credits, and is additionally clamped by a per-day cap so unlimited
 * replays with a fresh session id cannot farm XP indefinitely.
 *
 * Coverage is no longer trusted from the client: the caller sends a per-card
 * breakdown ({@link QuizSessionAnswerParams}) and the server re-derives the
 * aggregate coverage/answered-count itself, which also lets it compute
 * per-tag weak spots and bridge a poor session back to a specific lesson.
 */
export class FlashcardQuizSessionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly userFlashcardStatsProjectionService: UserFlashcardStatsProjectionService,
        private readonly contentRagRetrievalService: CourseRagRetrievalService,
    ) {}

    /**
     * Record a finished quick-quiz session and grant its XP reward.
     *
     * The reward is `min(remainingDailyHeadroom, MAX_XP_PER_SESSION, round(coverage * cards * PER_CARD_XP))`
     * where `coverage`/`cards` are re-derived SERVER-SIDE from the per-card
     * answer breakdown (never trusted from the client). The whole grant is
     * idempotent on `(source = flashcardQuiz, refId = sessionId)`: a replay
     * records nothing and returns `xpEarned = 0`.
     *
     * @param params - {@link CompleteFlashcardQuizSessionParams}
     * @returns the XP granted this call (0 on an idempotent replay or an
     * already-capped day), the day's cap state, this session's weakest tags,
     * and the AI Mock Interview readiness signal.
     *
     * @example
     * await service.complete({
     *     userId, sessionId, courseId,
     *     answers: [{ cardId: "c1", correctBlanks: 2, totalBlanks: 3 }],
     * })
     */
    async complete(
        {
            userId,
            sessionId,
            courseId,
            answers,
        }: CompleteFlashcardQuizSessionParams,
    ): Promise<CompleteFlashcardQuizSessionResult> {
        // clamp the answered-card count to a sane range so a spoofed or buggy
        // client cannot inflate the reward past the per-session ceiling by
        // submitting an absurdly long answers array
        const clampedAnswers = answers.slice(0,
            MAX_ANSWERED_CARDS)
        const cards = clampedAnswers.length

        // SERVER-SIDE coverage: average of each card's own correct/total ratio
        // (not client-sent) ΓÇö a card with totalBlanks=0 contributes 0 rather
        // than dividing by zero. This is the fix for the client-trusted-score
        // exploit: the aggregate is derived here, from the per-card payload.
        const coverage = cards === 0
            ? 0
            : clampedAnswers.reduce(
                (acc, answer) => acc + this.cardCoverage(answer),
                0,
            ) / cards

        // coverage-weighted reward, hard-capped so one session can never exceed the ceiling
        const sessionAmount = Math.min(MAX_XP_PER_SESSION,
            Math.round(coverage * cards * PER_CARD_XP))

        // weak-tags + readiness are read-only insight, independent of the XP
        // grant/idempotency path ΓÇö compute them even on a replay so the recap
        // still has something to show
        const [
            weakTags,
            readiness,
        ] = await Promise.all([
            this.computeWeakTags(clampedAnswers),
            this.computeReadiness(userId),
        ])

        // write the grant in one transaction so the idempotency check, the daily-cap
        // sum, and the ledger write cannot interleave with a concurrent replay
        const {
            xpEarned,
            dailyCapReached,
        } = await this.entityManager.transaction(async (manager) => {
            // idempotency gate: if this session already produced a ledger row, a replay
            // (double-submit / retry) must not credit again ΓåÆ return zero without writing
            const existing = await manager.findOne(
                XpHistoryEntity,
                {
                    where: {
                        source: XpSource.FlashcardQuiz,
                        refId: sessionId,
                    },
                    select: {
                        id: true,
                    },
                },
            )
            if (existing) {
                return {
                    xpEarned: 0,
                    dailyCapReached: false,
                }
            }

            // "resume flashcard quiz session" (2026-07-08): flip the persisted
            // draw (if `sessionId` is one ΓÇö a server-issued
            // `startFlashcardQuizSession` id, scoped to the CALLER's own
            // enrollment) to "completed" so it stops surfacing as resumable via
            // `myInProgressFlashcardQuizSession`. A no-op (never throws) when
            // `sessionId` does not match any owned in-progress row ΓÇö an older
            // client that never called `startFlashcardQuizSession` still sends
            // a client-generated id here, which simply matches nothing.
            //
            // "history + stats" (2026-07-08): also snapshot `coverage` and
            // `weakTags` here (both already computed above, independent of the
            // XP grant) ΓÇö this and the `xpEarned` update below let
            // `myFlashcardQuizHistory`/`myFlashcardQuizStats` read a finished
            // session's outcome straight off its own row, without re-deriving
            // coverage from `results` or joining `xp_histories`. Sitting AFTER
            // the idempotency check above, a replay never re-touches the row.
            // WHERE `status: Not("completed")` (loosened 2026-07-12 ΓÇö was
            // `status: "in_progress"`; see `FlashcardDueReviewSessionService
            // .complete`'s doc for the full root-cause) so a row raced to
            // "abandoned" by a concurrent `start()` still gets its real
            // completion recorded instead of silently matching zero rows (an
            // older client's session id that never called
            // `startFlashcardQuizSession` still matches nothing, same as
            // before ΓÇö the row itself doesn't exist under that id).
            // Ownership is a two-level nested relation (enrollment ΓåÆ user),
            // which a bare `update()` cannot express: TypeORM compiles `update`
            // to an UpdateQueryBuilder with no JOINs, so a nested-relation WHERE
            // throws "Cannot find alias for relation". Resolve ownership with a
            // `findOne` (which CAN join) first, then update by the scalar `id` +
            // the replay-safe `status` guard ΓÇö mirroring `sync()`.
            const owned = await manager.findOne(
                FlashcardQuizSessionEntity,
                {
                    where: {
                        id: sessionId,
                        enrollment: {
                            user: {
                                id: userId,
                            },
                        },
                    },
                    select: {
                        id: true,
                    },
                },
            )
            if (owned) {
                await manager.update(
                    FlashcardQuizSessionEntity,
                    {
                        id: sessionId,
                        status: Not("completed"),
                    },
                    {
                        status: "completed",
                        coverage,
                        weakTags,
                    },
                )
            }

            // sum today's (VN calendar day) FlashcardQuiz XP for this (user, course) ΓÇö
            // the daily cap headroom is the ceiling minus what has already been granted
            const grantedToday = await this.sumTodayQuizXp(manager,
                userId,
                courseId)
            const headroom = Math.max(0,
                DAILY_QUIZ_XP_CAP - grantedToday)
            const amount = Math.min(sessionAmount,
                headroom)

            // nothing left to grant today ΓÇö record no ledger row (an idempotency
            // replay must find nothing here later either, which is correct: a
            // zero-XP day-capped call has nothing to become idempotent about)
            if (amount <= 0) {
                return {
                    xpEarned: 0,
                    dailyCapReached: true,
                }
            }

            // append the single xp_histories row ΓÇö feeds streak / weekly XP /
            // course leaderboard, which all read xp_histories. Also grants the
            // flat Coin reward (anchored to lessonRead) on any session that
            // actually earned XP this cap window; writeXpHistory guards on
            // (source, refId), so the grant is doubly safe.
            await writeXpHistory({
                entityManager: manager,
                userId,
                courseId,
                source: XpSource.FlashcardQuiz,
                amount,
                points: FLAT_POINTS.flashcardQuizSession,
                refId: sessionId,
            })

            // snapshot the ACTUAL granted XP (post daily-cap clamp) onto the
            // row ΓÇö only known now, after the headroom calc above, so this is
            // a second update rather than folding into the first
            await manager.update(
                FlashcardQuizSessionEntity,
                {
                    id: sessionId,
                },
                {
                    xpEarned: amount,
                },
            )

            return {
                xpEarned: amount,
                // the day is "capped" from this call's perspective when the clamp
                // actually reduced the reward below what coverage alone would earn
                dailyCapReached: amount < sessionAmount,
            }
        })

        return {
            xpEarned,
            dailyCapReached,
            weakTags,
            readiness,
        }
    }

    /** One card's own correct/total ratio, guarding against a zero denominator. */
    private cardCoverage(answer: QuizSessionAnswerParams): number {
        // clamp inputs first ΓÇö a spoofed client could send correctBlanks > totalBlanks
        // or negative counts; both are nonsensical for a ratio
        const total = Math.max(0,
            Math.trunc(answer.totalBlanks))
        if (total === 0) {
            // no blanks to grade on this card ΓåÆ contributes 0, not a divide-by-zero
            return 0
        }
        const correct = Math.max(0,
            Math.min(Math.trunc(answer.correctBlanks),
                total))
        return correct / total
    }

    /** Sum today's (VN calendar day) FlashcardQuiz XP already granted to this (user, course) pair. */
    private async sumTodayQuizXp(
        manager: EntityManager,
        userId: string,
        courseId: string,
    ): Promise<number> {
        const row = await manager
            .createQueryBuilder(XpHistoryEntity,
                "history")
            .select("COALESCE(SUM(history.amount), 0)",
                "sum")
            .where("history.user_id = :userId",
                {
                    userId,
                })
            .andWhere("history.course_id = :courseId",
                {
                    courseId,
                })
            .andWhere("history.source = :source",
                {
                    source: XpSource.FlashcardQuiz,
                })
            // VN calendar day, matching the daily-quest convention (Asia/Ho_Chi_Minh),
            // so the cap resets at VN midnight rather than UTC midnight
            .andWhere(
                "(history.created_at AT TIME ZONE :timezone)::date = (now() AT TIME ZONE :timezone)::date",
                {
                    timezone: DAILY_CAP_TIMEZONE,
                },
            )
            .getRawOne<QuizXpSumRow>()
        return Number(row?.sum) || 0
    }

    /**
     * Rank this session's technology tags by lowest coverage (weakest first),
     * resolving a "review this lesson" deep link for a tag when its cards'
     * owning deck(s) map to EXACTLY one module/content ΓÇö an ambiguous mapping
     * (a deck spanning zero or multiple modules/contents) omits the link
     * fields rather than fabricating one.
     *
     * @param answers - the clamped per-card breakdown for this session.
     * @returns the weakest tags, capped at {@link MAX_WEAK_TAGS}.
     */
    private async computeWeakTags(
        answers: Array<QuizSessionAnswerParams>,
    ): Promise<Array<QuizSessionWeakTagResult>> {
        if (answers.length === 0) {
            // nothing answered ΓåÆ nothing to rank
            return []
        }

        // load the answered cards' tags + their deck's content/module links in one
        // query ΓÇö this is the per-card breakdown the client no longer needs to
        // pre-aggregate; the server derives tag coverage from it directly
        const cardIds = answers.map((answer) => answer.cardId)
        const cards = await this.entityManager.find(
            FlashcardCardEntity,
            {
                where: {
                    id: In(cardIds),
                },
                relations: {
                    // deck loaded for its courseId ΓÇö the "review this lesson" link is
                    // now resolved via RAG (searchCourse), not the old deckΓåÆcontent/
                    // module relations (removed).
                    deck: true,
                },
            },
        )
        const cardById = new Map(cards.map((card) => [
            card.id,
            card,
        ]))

        // accumulate per-tag correct/total across every card that carries the tag ΓÇö
        // a card can carry multiple tags, so it contributes to each tag's totals
        const correctByTag = new Map<string, number>()
        const totalByTag = new Map<string, number>()
        // remember one representative card per tag so we can resolve its deep link
        // (first card seen carrying the tag ΓÇö good enough for a "review this" nudge)
        const representativeCardByTag = new Map<string, FlashcardCardEntity>()
        for (const answer of answers) {
            const card = cardById.get(answer.cardId)
            if (!card) {
                // the card id was not found (deleted / bad input) ΓÇö skip it silently,
                // its blanks simply do not contribute to any tag
                continue
            }
            const coverage = this.cardCoverage(answer)
            for (const tag of card.tags) {
                correctByTag.set(tag,
                    (correctByTag.get(tag) ?? 0) + coverage)
                totalByTag.set(tag,
                    (totalByTag.get(tag) ?? 0) + 1)
                if (!representativeCardByTag.has(tag)) {
                    representativeCardByTag.set(tag,
                        card)
                }
            }
        }

        // average coverage per tag, ranked weakest (lowest coverage) first
        const ranked = [...totalByTag.entries()]
            .map(([
                tag,
                total,
            ]) => ({
                tag,
                coverage: total === 0 ? 0 : (correctByTag.get(tag) ?? 0) / total,
            }))
            .sort((prev, next) => prev.coverage - next.coverage)
            .slice(0,
                MAX_WEAK_TAGS)

        // resolve each tag's deep link via RAG (query = the weak tag itself ΓåÆ the
        // most relevant lesson in this course), scoped by the representative card's
        // deck courseId
        return Promise.all(ranked.map(async ({ tag, coverage }) => {
            const courseId = representativeCardByTag.get(tag)?.deck?.courseId
            const link = await this.resolveWeakTagLink(courseId,
                tag)
            return {
                tag,
                coverage,
                ...link,
            }
        }))
    }

    /**
     * Resolve a weak tag's "review this lesson" link via RAG ΓÇö semantic-search the
     * course's indexed content for the tag and deep-link the best-matching lesson
     * (+ its owning module). Replaces the old deckΓåÆcontent/module relations
     * (removed): the association is now derived from what the course actually
     * teaches, not a stored many-to-many. Degrades to no link when the course id
     * or tag is missing, retrieval misses, or the matched content row is gone.
     *
     * @param courseId - the course to search within (the tag's deck's course).
     * @param query - the weak tag (the concept to find a lesson for).
     * @returns `{ moduleId?, contentId? }`, empty when nothing relevant resolves.
     */
    private async resolveWeakTagLink(
        courseId: string | undefined,
        query: string,
    ): Promise<Pick<QuizSessionWeakTagResult, "moduleId" | "contentId">> {
        const trimmed = query.trim()
        if (!courseId || !trimmed) {
            return {
            }
        }
        const { hits } = await this.contentRagRetrievalService.searchCourse({
            courseId,
            query: trimmed,
        })
        // only a lesson (content/code chunk) is a valid "review this" target ΓÇö a
        // challenge/flashcard/milestone hit is not a lesson to re-read
        const lessonHit = hits.find(
            (hit) => hit.kind === "content" || hit.kind === "code",
        )
        if (!lessonHit) {
            return {
            }
        }
        const content = await this.entityManager.findOne(
            ContentEntity,
            {
                where: {
                    id: lessonHit.contentId,
                },
                select: {
                    id: true,
                    moduleId: true,
                },
            },
        )
        return content
            ? {
                contentId: content.id,
                moduleId: content.moduleId,
            }
            : {
            }
    }

    /**
     * Cheap proxy readiness signal for the AI Mock Interview cross-link, reused
     * from the existing flashcard-stats projection (retention rate) rather than
     * building new cross-session tracking for this MVP pass.
     *
     * @param userId - the learner whose readiness to read.
     * @returns the proxy value, the unlock threshold, and whether it is met.
     */
    private async computeReadiness(
        userId: string,
    ): Promise<CompleteFlashcardQuizSessionResult["readiness"]> {
        // reuse the myFlashcardStats projection read (streak / retention / totals) ΓÇö
        // retentionRate (0-100) is the cheapest available proxy for "how well is
        // this learner doing", with no new tracking needed for this pass
        const stats = await this.userFlashcardStatsProjectionService.getStats({
            userId,
        })
        // reuse the job-readiness "building" band threshold as the unlock bar ΓÇö
        // it is already the platform's calibrated "showing real competence" line,
        // so a second bespoke threshold would just duplicate that judgment call
        const threshold = JOB_READINESS_BUILDING_THRESHOLD
        return {
            currentAvg: stats.retentionRate,
            threshold,
            unlocked: stats.retentionRate >= threshold,
        }
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    In,
    MoreThanOrEqual,
    Not,
} from "typeorm"
import {
    FlashcardDeckEntity,
    FlashcardReviewSessionEntity,
    InjectPrimaryPostgreSQLEntityManager,
    UserFlashcardReviewEntity,
} from "@modules/databases"
import {
    FlashcardDeckNotFoundException,
} from "@modules/exceptions"
import {
    UserService,
} from "../user"
import type {
    CompleteFlashcardReviewSessionParams,
    CompleteFlashcardReviewSessionResult,
    FindFlashcardReviewSessionByIdParams,
    FindMyInProgressFlashcardReviewSessionParams,
    FlashcardReviewSessionByIdResultData,
    MyInProgressFlashcardReviewSessionResultData,
    StartFlashcardReviewSessionParams,
    StartFlashcardReviewSessionResult,
    SyncFlashcardReviewSessionProgressParams,
    SyncFlashcardReviewSessionProgressResult,
} from "./types/flashcard-review-session"

/**
 * How far back a session's last sync may be for it to still be offered as
 * resumable ΓÇö same reasoning as `MyInProgressFlashcardQuizSessionService`'s
 * own `RESUME_WINDOW_HOURS`: a session synced longer ago than this is treated
 * as effectively abandoned even though `startFlashcardReviewSession` has not
 * yet flipped its status (that only happens when the SAME enrollment+deck
 * starts a NEW draw).
 */
const RESUME_WINDOW_HOURS = 24

@Injectable()
/**
 * Business logic for the resumable flashcard reviewer ("Hß╗ìc thß║╗") session ΓÇö
 * mirrors {@link import("./flashcard-quiz-session.service").FlashcardQuizSessionService}'s
 * resumable-draw shape, but scoped to ONE deck (not a whole course) and with
 * NO coverage/weakTags/XP-grant complexity: the actual SM-2 grading still
 * happens per-card through the existing `reviewFlashcard` mutation
 * ({@link import("./flashcard-review.service").FlashcardReviewService.review}); this
 * service is purely a resumable progress/bookkeeping wrapper around a
 * sequence of those calls, so history/stats can be built for review mode the
 * same way they already exist for quiz mode.
 *
 * XP DECISION: `reviewFlashcard` grants no XP today and writes no
 * `xp_histories` row. To avoid inventing a new, unreviewed XP-granting
 * mechanism for this MVP pass, `xpEarned` on `flashcard_review_sessions` is
 * treated as a CLIENT-REPORTED BOOKKEEPING SNAPSHOT ONLY ΓÇö `sync`/`complete`
 * below persist whatever value the caller sends, with NO `xp_histories`
 * insert, NO `XpSource` addition, and NO daily-cap logic. This keeps parity
 * with `reviewFlashcard`'s own current behavior (no XP) instead of silently
 * introducing a parallel economy.
 */
export class FlashcardReviewSessionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly userService: UserService,
    ) {}

    /**
     * Persist ONE resumable flashcard review session draw over a single deck,
     * retiring any PRIOR "in_progress" draw for the same enrollment+deck first
     * so a learner never has two resumable review sessions on the same deck
     * at once ΓÇö mirrors `FlashcardQuizSessionService`'s own "abandon prior
     * in_progress row" step (there scoped by enrollment alone; here further
     * scoped by deck, since review sessions are per-deck).
     *
     * @param params - {@link StartFlashcardReviewSessionParams}
     * @returns the newly-persisted session's id.
     * @throws FlashcardDeckNotFoundException when the deck does not exist.
     */
    async start(
        {
            userId,
            deckId,
            cardIds,
            mode = "full",
        }: StartFlashcardReviewSessionParams,
    ): Promise<StartFlashcardReviewSessionResult> {
        const deck = await this.entityManager.findOne(
            FlashcardDeckEntity,
            {
                where: {
                    id: deckId,
                },
                select: {
                    id: true,
                    course: {
                        id: true,
                    },
                },
                relations: {
                    course: true,
                },
            },
        )
        if (!deck) {
            throw new FlashcardDeckNotFoundException({
                flashcardDeckId: deckId,
            })
        }

        // "Chß╗ë thß║╗ cß║ºn ├┤n" (thß║ºy 2026-07-13): narrow the requested cardIds down to
        // the ones actually DUE ΓÇö no review row yet (never learned) OR past their
        // `due_at`. Same predicate as `FlashcardDeckService.annotateViewerStats`'
        // `dueCount` (keyed by user_id so the count shown on the deck card and the
        // set persisted here match exactly), and the whole point of the "qu├¬n"
        // mode: cards graded Good/Easy recently (due_at in the future) drop out.
        // A filter that would leave NOTHING keeps the full set ΓÇö never persist an
        // empty draw (the modal already disables this mode when dueCount is 0, so
        // this is only a defensive floor).
        let effectiveCardIds = cardIds
        if (mode === "due") {
            const now = new Date()
            const reviews = await this.entityManager.find(
                UserFlashcardReviewEntity,
                {
                    where: {
                        userId,
                        flashcardCard: {
                            id: In(cardIds),
                        },
                    },
                    select: {
                        dueAt: true,
                        flashcardCard: {
                            id: true,
                        },
                    },
                    relations: {
                        flashcardCard: true,
                    },
                },
            )
            const dueAtByCardId = new Map<string, Date | null>()
            for (const review of reviews) {
                dueAtByCardId.set(review.flashcardCard.id,
                    review.dueAt)
            }
            const dueCardIds = cardIds.filter((id) => {
                // a card with NO review row was never in the map ΓåÆ never reviewed ΓåÆ due.
                // `has` distinguishes that from a row whose `dueAt` is null.
                if (!dueAtByCardId.has(id)) {
                    return true
                }
                const dueAt = dueAtByCardId.get(id)
                // a null due_at (unscheduled) counts as due; else due when past due_at
                return !dueAt || dueAt <= now
            })
            if (dueCardIds.length > 0) {
                effectiveCardIds = dueCardIds
            }
        }

        // review sessions are anchored to the SAME (user, course) trial
        // enrollment startFlashcardQuizSession/reviewFlashcard already resolve
        // ΓÇö the course is derived from the deck itself since the request only
        // carries deckId, not courseId.
        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            deck.course.id,
        )

        // retire the enrollment+deck's previous in-flight draw (if any) BEFORE
        // persisting the new one, so resume-lookup never has two candidates.
        await this.entityManager.update(
            FlashcardReviewSessionEntity,
            {
                enrollment: {
                    id: enrollment.id,
                },
                deck: {
                    id: deckId,
                },
                status: "in_progress",
            },
            {
                status: "abandoned",
            },
        )

        const session = await this.entityManager.save(
            FlashcardReviewSessionEntity,
            {
                enrollment,
                deck: {
                    id: deckId,
                },
                cardIds: effectiveCardIds,
                currentIndex: 0,
                reviewedCount: 0,
                gradedIndexes: [],
                xpEarned: 0,
                status: "in_progress",
            },
        )

        return {
            sessionId: session.id,
        }
    }

    /**
     * Sync an in-flight flashcard review session's position + progress ΓÇö
     * ownership-scoped, silently no-ops (never throws) for a session that is
     * not found/owned or no longer "in_progress", same reasoning as
     * `SyncFlashcardQuizSessionProgressHandler` (a background periodic sync
     * must never surface an error toast mid-review).
     *
     * @param params - {@link SyncFlashcardReviewSessionProgressParams}
     * @returns whether the sync was applied.
     */
    async sync(
        {
            userId,
            sessionId,
            currentIndex,
            reviewedCount,
            gradedIndexes,
            xpEarned,
        }: SyncFlashcardReviewSessionProgressParams,
    ): Promise<SyncFlashcardReviewSessionProgressResult> {
        const session = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                    status: true,
                },
            },
        )

        if (!session || session.status !== "in_progress") {
            return {
                success: false,
            }
        }

        await this.entityManager.update(
            FlashcardReviewSessionEntity,
            {
                id: session.id,
            },
            {
                currentIndex,
                reviewedCount,
                // only overwrite the graded-index set when the caller sent one
                // ΓÇö omitting it must leave the column untouched (same tolerance
                // the rest of the sync payload has), not wipe it to undefined.
                ...(gradedIndexes !== undefined ? {
                    gradedIndexes,
                } : {
                }),
                xpEarned,
            },
        )

        return {
            success: true,
        }
    }

    /**
     * Record a finished flashcard review session ΓÇö flips the row to
     * "completed" and snapshots the final reviewed-count/xpEarned the caller
     * reports. Ownership-scoped via `status: Not("completed")` (loosened
     * 2026-07-12 ΓÇö was `status: "in_progress"`; see
     * `FlashcardDueReviewSessionService.complete`'s own doc for the full
     * root-cause: a STRICT `"in_progress"` match silently updates ZERO rows
     * ΓÇö no throw ΓÇö whenever the row got raced to "abandoned" by a concurrent
     * `start()` first, permanently stranding the session un-completed even
     * though the FE mutation call itself reported success). `Not("completed")`
     * stays replay-safe (refuses to re-flip an already-completed row) while
     * tolerating a raced "abandoned" status.
     *
     * NO XP is granted here ΓÇö see the class doc's XP DECISION. `xpEarned` is
     * echoed straight through as a bookkeeping snapshot, never written to
     * `xp_histories`.
     *
     * @param params - {@link CompleteFlashcardReviewSessionParams}
     * @returns the reviewed-count/xpEarned snapshotted onto the row.
     */
    async complete(
        {
            userId,
            sessionId,
            reviewedCount,
            xpEarned,
        }: CompleteFlashcardReviewSessionParams,
    ): Promise<CompleteFlashcardReviewSessionResult> {
        // Ownership is a two-level nested relation (enrollment ΓåÆ user), which a
        // bare `update()` cannot express: TypeORM compiles `update` to an
        // UpdateQueryBuilder that has no JOINs, so a nested-relation WHERE throws
        // "Cannot find alias for relation". Resolve ownership with a `findOne`
        // (which CAN join) first, then update by the scalar `id` + the
        // replay-safe `status` guard ΓÇö mirroring `sync()` in this same service.
        const owned = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                },
            },
        )
        if (owned) {
            await this.entityManager.update(
                FlashcardReviewSessionEntity,
                {
                    id: sessionId,
                    status: Not("completed"),
                },
                {
                    status: "completed",
                    reviewedCount,
                    xpEarned,
                },
            )
        }

        return {
            reviewedCount,
            xpEarned,
        }
    }

    /**
     * Find the most recent `status = "in_progress"` review session, synced
     * within {@link RESUME_WINDOW_HOURS}, for the caller's enrollment scoped
     * to ONE deck ΓÇö mirrors `MyInProgressFlashcardQuizSessionService.find`,
     * further scoped by deck (review sessions are per-deck, quiz sessions are
     * per-course).
     *
     * @param params - {@link FindMyInProgressFlashcardReviewSessionParams}
     * @returns the resumable session, or null when there is none.
     * @throws FlashcardDeckNotFoundException when the deck does not exist.
     */
    async findInProgress(
        {
            userId,
            deckId,
        }: FindMyInProgressFlashcardReviewSessionParams,
    ): Promise<MyInProgressFlashcardReviewSessionResultData | null> {
        const deck = await this.entityManager.findOne(
            FlashcardDeckEntity,
            {
                where: {
                    id: deckId,
                },
                select: {
                    id: true,
                    course: {
                        id: true,
                    },
                },
                relations: {
                    course: true,
                },
            },
        )
        if (!deck) {
            throw new FlashcardDeckNotFoundException({
                flashcardDeckId: deckId,
            })
        }

        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            deck.course.id,
        )

        const resumeWindowStart = new Date(
            Date.now() - RESUME_WINDOW_HOURS * 60 * 60 * 1000,
        )

        const session = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    enrollment: {
                        id: enrollment.id,
                    },
                    deck: {
                        id: deckId,
                    },
                    status: "in_progress",
                    updatedAt: MoreThanOrEqual(resumeWindowStart),
                },
                order: {
                    updatedAt: "DESC",
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }

    /**
     * Find a review session directly by its id (ownership-checked against the
     * caller) ΓÇö no `deckId` needed upfront, unlike {@link findInProgress}. The
     * FE's unified `/review/sessions/[sessionId]` route uses this to resolve
     * full context (deck + progress) from just the id in the URL (thß║ºy
     * 2026-07-11: "session ─æ├ú persist hß║┐t rß╗ôi", no `deckId` query hint
     * needed). NOT window/status-scoped like `findInProgress` ΓÇö a direct link
     * to a completed/abandoned session still resolves (so a stale link shows
     * the real state instead of a false 404); the caller decides what to do
     * with a non-"in_progress" row.
     *
     * @param params - {@link FindFlashcardReviewSessionByIdParams}
     * @returns the session with its deck identity attached, or null when not
     * found/not owned by the caller.
     */
    async findById(
        {
            userId,
            sessionId,
        }: FindFlashcardReviewSessionByIdParams,
    ): Promise<FlashcardReviewSessionByIdResultData | null> {
        const session = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                relations: {
                    deck: true,
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            deckId: session.deckId,
            deckTitle: session.deck.title,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }
}

