                        // repetitions becomes 1 on ANY successful grade, and rep===1 always
                        // schedules 1 day regardless of which grade got there
                        const result = service.previewIntervals(NEW_CARD_STATE)

                        expect(result).toEqual({
                            again: 1,
                            hard: 1,
                            good: 1,
