import {
    Injectable,
} from "@nestjs/common"
import {
    ConsultantEntity,
} from "@modules/databases"
import {
    CV_SCORE_UNLOCK_THRESHOLD,
} from "./constants"
import type {
    GetBestCvScoreParams,
} from "./types"
import {
    CvVerificationService,
} from "./cv-verification.service"

@Injectable()
/**
 * Gates a consultant's direct contact details (email / phone / Zalo /
 * LinkedIn) behind the requesting viewer's best-ever CV score. Below
 * {@link CV_SCORE_UNLOCK_THRESHOLD}, the contact fields are nulled out
 * server-side ΓÇö never sent over the wire ΓÇö so a headhunter's phone number
 * cannot be scraped by an anonymous or low-scoring viewer.
 *
 * Applied by the `headhuntingCompany(ies)` / `consultant(s)` query handlers,
 * which fetch consultant documents from Elasticsearch and pass each one
 * through {@link gateConsultant} before returning it to the client.
 */
export class ConsultantContactGateService {
    constructor(
        private readonly cvVerificationService: CvVerificationService,
    ) {}

    /**
     * Computes the viewer's CV trust score ΓÇö **deterministic, count-independent,
     * no AI/CV-prose involved** (2026-07-05: replaced the old AI-judged
     * `cv_generations.score` rubric entirely; see
     * {@link import("./cv-verification.service").CvVerificationService.scoreOf}).
     * A pure function of {@link import("./cv-verification.service").CvVerificationService.resolveLevel}
     * (passed capstone / graded challenge, existence-checked) ΓÇö **source-blind
     * AND upload-vs-generate-irrelevant by construction**, since there is no
     * CV row read here at all. This gate stays OPEN for everyone ("H╞░ß╗¢ng A",
     * see `CV-VERIFIED-TRUST-TIER-WORKFLOW.md`): StarCi sells CREDIBILITY, not
     * ACCESS.
     *
     * CAUTION: placeholder step values pending calibration ΓÇö see
     * {@link import("./cv-verification.service").CvVerificationService.scoreOf}.
     *
     * @param params - The viewer to score.
     * @returns 100 / 50 / 0 (see `scoreOf`), or `0` for an anonymous viewer.
     */
    async getBestCvScore(
        {
            userId,
        }: GetBestCvScoreParams,
    ): Promise<number> {
        // anonymous viewer ΓåÆ always locked, skip the lookup entirely
        if (!userId) {
            return 0
        }

        const level = await this.cvVerificationService.resolveLevel(userId)
        return this.cvVerificationService.scoreOf(level)
    }

    /**
     * Mutates one consultant document in place: nulls out its contact fields
     * and sets `contactUnlocked` / `cvScoreUnlockThreshold` based on the
     * viewer's best CV score.
     *
     * @param consultant - Consultant document to gate (mutated in place).
     * @param bestCvScore - The requesting viewer's best-ever CV score (from
     *   {@link getBestCvScore}); pass `0` for anonymous viewers.
     * @returns The same `consultant` reference, for convenient chaining in
     *   `.map()` calls.
     */
    gateConsultant(
        consultant: ConsultantEntity,
        bestCvScore: number,
    ): ConsultantEntity {
        const unlocked = bestCvScore >= CV_SCORE_UNLOCK_THRESHOLD

        // always stamp the two new fields so the FE can render the gate
        // ("cß║ºn ─æiß╗âm CV ΓëÑ X") regardless of unlock state
        consultant.contactUnlocked = unlocked
        consultant.cvScoreUnlockThreshold = CV_SCORE_UNLOCK_THRESHOLD

        // below threshold ΓåÆ strip every direct-contact field server-side so
        // it never reaches the wire, not just hidden client-side
        if (!unlocked) {
            consultant.email = null
            consultant.phoneNumber = null
            consultant.zaloNumber = null
            consultant.linkedinUrl = null
        }

        return consultant
    }

    /**
     * Gates every consultant in a list using the same viewer score, mirroring
     * {@link gateConsultant} for list query paths (`consultants`,
     * `headhuntingCompany.consultants`).
     *
     * @param consultants - Consultant documents to gate (mutated in place).
     * @param bestCvScore - The requesting viewer's best-ever CV score.
     * @returns The same array reference, for convenient chaining.
     */
    gateConsultants(
        consultants: Array<ConsultantEntity>,
        bestCvScore: number,
    ): Array<ConsultantEntity> {
        consultants.forEach((consultant) => this.gateConsultant(consultant,
            bestCvScore))
        return consultants
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    CvVerificationLevel,
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases"
import type {
    EntityManager,
} from "typeorm"
import type {
    CvVerificationUserIdRow,
    ResolveCvVerificationLevelForCourseParams,
    ResolveCvVerificationLevelsParams,
} from "./types"

@Injectable()
/**
 * Classifies candidates into a {@link CvVerificationLevel} ΓÇö a recruiter TRUST
 * signal tied to REAL, graded StarCi work (never to payment or CV count). A
 * strong external developer who only uploaded a CV is `SelfReported`; graded
 * challenge work is `ActivityBacked`; a passed capstone is `CapstoneVerified`.
 *
 * Used by the recruiter marketplace ({@link import("../../../features/api/core/graphql/queries/users/talent-candidates/talent-candidates.service").TalentCandidatesService})
 * to badge candidates and break depth ties (verified above self-reported).
 * Deliberately does NOT touch the CV-score contact gate
 * ({@link import("./consultant-contact-gate.service").ConsultantContactGateService})
 * ΓÇö this is an additive trust tier, not a new access lock.
 */
export class CvVerificationService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
    ) {}

    /**
     * Classifies a BATCH of users into their verification level with two batched
     * existence probes (passed-capstone, graded-challenge). Batch-shaped so the
     * marketplace can classify a whole candidate page in two queries.
     *
     * @param params - {@link ResolveCvVerificationLevelsParams}
     * @returns a map of `userId ΓåÆ level`; every requested user is present (defaults to `SelfReported`).
     *
     * @example
     * const levels = await service.resolveLevels({ userIds })
     * levels.get(userId) // CvVerificationLevel.CapstoneVerified
     */
    async resolveLevels(
        {
            userIds,
        }: ResolveCvVerificationLevelsParams,
    ): Promise<Map<string, CvVerificationLevel>> {
        // empty batch ΓåÆ nothing to classify, skip the DB round-trips
        if (userIds.length === 0) {
            return new Map()
        }

        // two existence probes over the whole batch in parallel ΓÇö each returns
        // the DISTINCT set of user ids that HAVE that class of graded StarCi work
        const [
            capstoneRows,
            challengeRows,
        ] = await Promise.all([
            this.loadUsersWithPassedCapstone(userIds),
            this.loadUsersWithGradedChallenge(userIds),
        ])

        // index both sets for O(1) membership tests during classification
        const capstoneUserIds = new Set(capstoneRows.map((row) => row.user_id))
        const challengeUserIds = new Set(challengeRows.map((row) => row.user_id))

        // classify every REQUESTED user (not just the ones with a row) so callers
        // always get a level back ΓÇö absent from both sets means self-reported
        const levels = new Map<string, CvVerificationLevel>()
        userIds.forEach((userId) => {
            // a passed capstone/milestone task is the strongest proof of real project work
            if (capstoneUserIds.has(userId)) {
                levels.set(userId,
                    CvVerificationLevel.CapstoneVerified)
                return
            }
            // else any AI-graded challenge submission still proves hands-on StarCi work
            if (challengeUserIds.has(userId)) {
                levels.set(userId,
                    CvVerificationLevel.ActivityBacked)
                return
            }
            // no graded StarCi work at all ΓåÆ the CV stands on self-reported claims only
            levels.set(userId,
                CvVerificationLevel.SelfReported)
        })
        return levels
    }

    /**
     * Convenience single-user classification (thin wrapper over
     * {@link resolveLevels}).
     *
     * @param userId - the user to classify.
     * @returns the user's verification level (defaults to `SelfReported`).
     */
    async resolveLevel(userId: string): Promise<CvVerificationLevel> {
        // reuse the batch path with a one-element batch so the SQL stays single-sourced
        const levels = await this.resolveLevels({
            userIds: [userId] 
        })
        // missing key can only happen for an empty input, which never reaches here
        return levels.get(userId) ?? CvVerificationLevel.SelfReported
    }

    /**
     * Deterministic "CV trust score" for a level ΓÇö REPLACES the old AI-judged
     * `cv_generations.score` rubric everywhere that number gated something
     * (recruiter contact, job-readiness). No AI, no CV prose involved: a pure
     * function of the existence-checked signal, so it is count-independent and
     * payment-independent by construction ΓÇö a learner with 1 enrollment who
     * passed a capstone scores identically to one with 5 enrollments who also
     * passed one, and nothing here can be inflated by writing more into a CV
     * (there is no CV text in this computation at all).
     *
     * CAPSTONE-ONLY SCORE (2026-07-05, teacher-approved). Only a passed
     * CAPSTONE (`CapstoneVerified`) produces a positive gating score. A merely
     * `ActivityBacked` learner (graded challenges but no capstone) scores 0
     * like `SelfReported`: challenges are practice exercises that never go on
     * the CV, so they must not silently unlock a recruiter's contact details
     * either ΓÇö "a recruiter trusts a real capstone project, not a pile of
     * graded exercises". The 3-level classification is still kept for the
     * marketplace tie-break ({@link rankOf}); it just no longer feeds the gate.
     *
     * CAUTION: the step value (100) and the downstream unlock threshold
     * ({@link import("./constants").CV_SCORE_UNLOCK_THRESHOLD}) are a
     * placeholder pending calibration ΓÇö deliberately NOT tuned yet (2026-07-05:
     * "khoan check ─æiß╗âm thß║¡t ─æ├ú, check ─æiß╗âm cv ─æß╗â fair cho mß╗ìi ng╞░ß╗¥i tr╞░ß╗¢c").
     * Fairness of the FORMULA is what's locked here; the THRESHOLD is not.
     *
     * @param level - the verification level to score.
     * @returns 100 (passed capstone) / 0 (activity-backed or self-reported).
     */
    scoreOf(level: CvVerificationLevel): number {
        switch (level) {
        case CvVerificationLevel.CapstoneVerified:
            return 100
        // challenges (activity-backed) do NOT count toward the CV/gate score ΓÇö
        // only a real passed capstone does; treated the same as self-reported
        case CvVerificationLevel.ActivityBacked:
        case CvVerificationLevel.SelfReported:
            return 0
        }
    }

    /**
     * Sort rank of a level ΓÇö higher = stronger StarCi proof. Lets the marketplace
     * break equal-depth ties by surfacing verified candidates above self-reported
     * ones without importing the enum's ordering into another module.
     *
     * @param level - the verification level to rank.
     * @returns 2 (capstone) / 1 (activity) / 0 (self-reported).
     */
    rankOf(level: CvVerificationLevel): number {
        // explicit switch keeps the ordering exhaustive + obvious at the call site
        switch (level) {
        case CvVerificationLevel.CapstoneVerified:
            return 2
        case CvVerificationLevel.ActivityBacked:
            return 1
        case CvVerificationLevel.SelfReported:
            return 0
        }
    }

    /**
     * Same classification as {@link resolveLevel}, but scoped to ONE course ΓÇö
     * "did this learner pass a capstone / get a challenge graded IN THIS
     * course's enrollment", not anywhere on the platform. Powers the
     * per-track CV pillar ({@link import("../../../features/api/core/graphql/queries/users/job-readiness/job-readiness.service").JobReadinessService}),
     * which is per-course by design ΓÇö reusing the platform-wide
     * {@link resolveLevel} there would let 1 unrelated capstone in ANOTHER
     * course inflate THIS track's depth, which is exactly the count/cross-track
     * leak the fair-monetization axiom forbids. Existence-checked (not summed)
     * within the course, so it stays count-independent the same way
     * {@link resolveLevel} is platform-wide.
     *
     * @param params - the learner + the course to scope the check to.
     * @returns the level, defaulting to `SelfReported` when neither signal is present.
     */
    async resolveLevelForCourse(
        {
            userId,
            courseId,
        }: ResolveCvVerificationLevelForCourseParams,
    ): Promise<CvVerificationLevel> {
        const [
            capstoneRow,
            challengeRow,
        ] = await Promise.all([
            this.entityManager.query<Array<CvVerificationUserIdRow>>(
                `
                SELECT DISTINCT e.user_id AS user_id
                FROM enrollments e
                JOIN user_milestone_tasks umt ON umt.enrollment_id = e.id
                JOIN user_milestone_task_attempts umta ON umta.user_milestone_task_id = umt.id
                WHERE e.user_id = $1 AND e.course_id = $2 AND umta.passed = true
                LIMIT 1
                `,
                [
                    userId,
                    courseId,
                ],
            ),
            this.entityManager.query<Array<CvVerificationUserIdRow>>(
                `
                SELECT DISTINCT ucs.user_id AS user_id
                FROM user_challenge_submissions ucs
                JOIN user_challenge_submission_attempts ucsa ON ucsa.user_challenge_submission_id = ucs.id
                JOIN enrollments e ON e.id = ucs.enrollment_id
                WHERE ucs.user_id = $1 AND e.course_id = $2 AND ucsa.score IS NOT NULL
                LIMIT 1
                `,
                [
                    userId,
                    courseId,
                ],
            ),
        ])

        if (capstoneRow.length > 0) {
            return CvVerificationLevel.CapstoneVerified
        }
        if (challengeRow.length > 0) {
            return CvVerificationLevel.ActivityBacked
        }
        return CvVerificationLevel.SelfReported
    }

    /**
     * Distinct users with ΓëÑ1 PASSED capstone/milestone task attempt, reached via
     * their enrollments. A passed capstone is the strongest verification signal.
     *
     * @param userIds - the candidate batch's user ids.
     * @returns one row per qualifying user id.
     */
    private async loadUsersWithPassedCapstone(userIds: Array<string>): Promise<Array<CvVerificationUserIdRow>> {
        // join enrollments ΓåÆ user_milestone_tasks ΓåÆ attempts, keep only passed
        // attempts, and collapse to one distinct user_id per qualifying user
        return this.entityManager.query<Array<CvVerificationUserIdRow>>(
            `
            SELECT DISTINCT e.user_id AS user_id
            FROM enrollments e
            JOIN user_milestone_tasks umt ON umt.enrollment_id = e.id
            JOIN user_milestone_task_attempts umta ON umta.user_milestone_task_id = umt.id
            WHERE e.user_id = ANY($1) AND umta.passed = true
            `,
            [
                userIds,
            ],
        )
    }

    /**
     * Distinct users with ΓëÑ1 AI-graded challenge submission attempt. A non-null
     * `score` means the attempt was actually processed/graded (regardless of
     * pass/fail) ΓÇö proof the user did + submitted real hands-on StarCi work,
     * unlike a bare uploaded CV. (Challenge attempts carry no `passed` boolean,
     * so "graded" is the cleanest available signal.)
     *
     * @param userIds - the candidate batch's user ids.
     * @returns one row per qualifying user id.
     */
    private async loadUsersWithGradedChallenge(userIds: Array<string>): Promise<Array<CvVerificationUserIdRow>> {
        // join submissions ΓåÆ attempts, keep only scored (graded) attempts, and
        // collapse to one distinct user_id per qualifying user
        return this.entityManager.query<Array<CvVerificationUserIdRow>>(
            `
            SELECT DISTINCT ucs.user_id AS user_id
            FROM user_challenge_submissions ucs
            JOIN user_challenge_submission_attempts ucsa ON ucsa.user_challenge_submission_id = ucs.id
            WHERE ucs.user_id = ANY($1) AND ucsa.score IS NOT NULL
            `,
            [
                userIds,
            ],
        )
    }
}

import type {
    EntityManager,
} from "typeorm"
import type {
    InstallmentPlanEntity,
} from "@modules/databases"

/**
 * One offered `Fixed`-plan term for a given base price ΓÇö the shape the price
 * preview surfaces so the payment modal can show "N months ┬╖ X/month ┬╖ total (+markup%)"
 * before checkout.
 */
export interface InstallmentOption {
    /** Number of monthly cycles (3, 6, or 12). */
    months: number
    /** Markup percent this term adds over the base price. */
    markupPercent: number
    /** Base price ├ù (1 + markup%), rounded ΓÇö the whole amount owed across the schedule. */
    totalAmountVnd: number
    /** `totalAmountVnd / months`, rounded ΓÇö the amount charged each cycle (incl. the first at checkout). */
    monthlyAmountVnd: number
}

/** Params for {@link import("../installment-plan.service").InstallmentPlanService.createFixedPlan}. */
export interface CreateFixedInstallmentPlanParams {
    /** The buyer. */
    userId: string
    /** The checkout transaction that funded the first cycle. */
    originTransactionId: string
    /** Every course this plan gates access to (locked/unlocked together). */
    lockedCourseIds: Array<string>
    /** Total amount owed across the whole schedule, markup already applied. */
    totalAmountVnd: number
    /** Number of months in the schedule (3, 6, or 12). */
    months: number
    /** Markup percent snapshot applied at checkout. */
    markupPercent: number
    /** Active transaction, when called inside one (e.g. from the reconcile worker). */
    entityManager?: EntityManager
}

/** Params for {@link import("../installment-plan.service").InstallmentPlanService.createFlexiblePoolPlan}. */
export interface CreateFlexiblePoolInstallmentPlanParams {
    /** The learner this legacy arrears balance belongs to. */
    userId: string
    /** Every course this plan gates access to (locked/unlocked together). */
    lockedCourseIds: Array<string>
    /** The REAL remaining arrears balance (backfill input, per-learner). */
    remainingVnd: number
    /** Percent of the current balance owed each cycle. Defaults to 10 (2026-07-05 decision). */
    minPaymentPercent?: number
    /** Absolute floor for the per-cycle minimum. Defaults to 500,000─æ (2026-07-05 decision). */
    minPaymentFloorVnd?: number
    /** When the first cycle under the new system is due. */
    nextDueAt: Date
    /** Active transaction, when called inside one (e.g. from the backfill script). */
    entityManager?: EntityManager
}

/** Params for {@link import("../installment-plan.service").InstallmentPlanService.recordPayment}. */
export interface RecordInstallmentPaymentParams {
    /** The plan being paid against. */
    planId: string
    /** The REAL amount just paid (may exceed the cycle's minimum ΓÇö always allowed). */
    paidAmountVnd: number
    /** Active transaction, when called inside one (e.g. from the reconcile worker). */
    entityManager?: EntityManager
}

/** Result of {@link import("../installment-plan.service").InstallmentPlanService.recordPayment}. */
export interface RecordInstallmentPaymentResult {
    /** The plan after applying the payment. */
    plan: InstallmentPlanEntity
    /** Whether the paid amount met (or exceeded) this cycle's minimum ΓÇö false leaves the plan `Overdue`. */
    metMinimum: boolean
    /** Whether this payment finished the plan (`Fixed`: every installment paid; `FlexiblePool`: balance reached zero). */
    completed: boolean
}

/** Params for {@link import("../installment-plan.service").InstallmentPlanService.applyPaymentForTransaction}. */
export interface ApplyInstallmentPaymentForTransactionParams {
    /** The succeeded `installmentPayment` transaction funding this cycle. */
    transactionId: string
    /** The plan this transaction pays a cycle of ({@link TransactionEntity.installmentPlanId}). */
    planId: string
    /** The amount actually charged ({@link TransactionEntity.amount}). */
    paidAmountVnd: number
    /** Active transaction, when called inside one (e.g. from the reconcile worker). */
    entityManager?: EntityManager
}

import {
    JobActionService,
    JobStalledService
} from "../atomic"
import {
    Injectable,
} from "@nestjs/common"
import {
    ActionType,
    InjectPrimaryPostgreSQLEntityManager,
    InstallmentPlanEntity,
    JobEntity,
    TransactionItemEntity
} from "@modules/databases"
import {
    InstallmentPlanService,
} from "../../installment-plan"
import {
    InjectSuperJson
} from "@modules/mixin"
import SuperJSON from "superjson"
import {
    v4 as uuidv4
} from "uuid"
import {
    Queue
} from "bullmq"
import type {
    EntityManager
} from "typeorm"
import {
    InjectQueue
} from "@nestjs/bullmq"
import {
    bullData,
    BullQueueName
} from "@modules/bullmq"
import {
    EnqueueEnrollJobParams,
    EnqueueEnrollmentsForTransactionParams,
    EnqueueEnrollmentsForTransactionResult
} from "../types"
import {
    envConfig 
} from "@modules/env"
import {
    sleepEnqueueUxDelay,
} from "../utils"

@Injectable()
/**
 * Service for enqueuing an enroll job.
 */
export class EnqueueEnrollJobService {
    constructor(
        private readonly jobActionService: JobActionService,
        private readonly jobStalledService: JobStalledService,
        @InjectSuperJson()
        private readonly superJson: SuperJSON,
        @InjectQueue(bullData[BullQueueName.Enroll].name)
        private readonly enrollQueue: Queue<string>,
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly installmentPlanService: InstallmentPlanService,
    ) { }

    /**
     * Fan a paid Enroll transaction out to one enroll job per course, covering both
     * multi-course orders (a `transaction_items` row per course) and legacy
     * single-course orders (the course carried directly on `transaction.course`).
     * Called by every gateway webhook + the reconcile worker on payment success.
     *
     * @param params - The paid Enroll transaction.
     * @returns The number of enroll jobs enqueued (0 = malformed transaction).
     */
    async enqueueForTransaction(
        {
            transaction,
        }: EnqueueEnrollmentsForTransactionParams,
    ): Promise<EnqueueEnrollmentsForTransactionResult> {
        // multi-course order ΓåÆ the courses live in transaction_items (transaction.course is null)
        const items = await this.entityManager.find(
            TransactionItemEntity,
            {
                where: {
                    transaction: {
                        id: transaction.id,
                    },
                },
            },
        )
        // resolve the course ids of this order (multi-course items, else the single
        // course on the transaction) ΓÇö drives both the per-course enroll fan-out AND
        // the installment plan's `lockedCourseIds` (all courses gated together)
        const courseIds = items.length > 0
            ? items.map((item) => item.courseId)
            : (transaction.courseId ? [transaction.courseId] : [])
        // neither items nor a course ΓåÆ malformed Enroll transaction; let the caller surface it
        if (courseIds.length === 0) {
            return {
                enqueuedCount: 0,
            }
        }
        // enqueue sequentially (AWAITED per line) so a broker failure propagates:
        // the webhook then returns non-2xx and the gateway re-delivers ΓåÆ no line stranded.
        // Each enroll job is idempotent per (user, course), so a re-delivery is safe.
        for (const courseId of courseIds) {
            await this.enqueue({
                userId: transaction.userId,
                courseId,
                transactionId: transaction.id,
            })
        }
        // installment (trß║ú g├│p) first cycle: create the Fixed plan ONCE per paid
        // checkout (the enroll jobs above grant access; this only records the
        // schedule + gated courses). Idempotent against re-delivery (webhook + poll)
        // by the plan's unique origin transaction.
        await this.createInstallmentPlanIfNeeded(transaction,
            courseIds)
        return {
            enqueuedCount: courseIds.length,
        }
    }

    /**
     * When a paid Enroll transaction carries installment intent (the buyer chose
     * trß║ú g├│p at checkout), create its `Fixed` {@link InstallmentPlanEntity} ΓÇö
     * exactly once. A no-op for a one-shot purchase (no `installmentMonths`) or a
     * re-delivered confirmation (a plan already exists for this origin transaction).
     *
     * @param transaction - The paid Enroll transaction (carries the installment snapshot).
     * @param lockedCourseIds - Every course this plan gates access to (locked/unlocked together).
     */
    private async createInstallmentPlanIfNeeded(
        transaction: EnqueueEnrollmentsForTransactionParams["transaction"],
        lockedCourseIds: Array<string>,
    ): Promise<void> {
        if (!transaction.installmentMonths || !transaction.installmentTotalVnd) {
            return
        }
        const existing = await this.entityManager.findOne(
            InstallmentPlanEntity,
            {
                where: {
                    originTransaction: {
                        id: transaction.id,
                    },
                },
            },
        )
        if (existing) {
            return
        }
        await this.installmentPlanService.createFixedPlan({
            userId: transaction.userId,
            originTransactionId: transaction.id,
            lockedCourseIds,
            totalAmountVnd: transaction.installmentTotalVnd,
            months: transaction.installmentMonths,
            markupPercent: transaction.installmentMarkupPercent ?? 0,
        })
    }

    /**
     * Enqueue an enroll job.
     * @param params - The parameters for enqueuing an enroll job.
     * @param params.userId - The ID of the user to enroll.
     * @param params.courseId - The ID of the course to enroll in.
     * @param params.jobId - The ID of the job to requeue.
     * @returns The job.
     */
    async enqueue(
        {
            transactionId,
            userId,
            courseId,
            jobId,
        }: EnqueueEnrollJobParams,
    ) {
        // get the job record
        let job: JobEntity | null = null
        if (jobId) {
            // requeue the job
            job = await this.jobStalledService.requeueJob(
                {
                    id: jobId,
                }
            )
        } else {
            // create a new job record
            job = await this.jobActionService.createJob({
                id: uuidv4(),
                userId,
                actionType: ActionType.Enroll,
                maxSteps: envConfig().job.enroll.maxSteps,
                payload: this.superJson.stringify(
                    {
                        transactionId,
                        userId,
                        courseId,
                    }
                ),
            })
        }
        // push the job to the broker ΓÇö AWAITED (not fire-and-forget): this runs on
        // the payment-finalize path, so returning before the broker job exists would
        // strand a paid transaction with no enroll job (and the gateway, already
        // 2xx'd, never retries). On failure mark the job failed AND rethrow so the
        // caller (webhook) returns non-2xx and the gateway re-delivers.
        try {
            await sleepEnqueueUxDelay()
            await this.enrollQueue.add(
                job.id,
                job.payload,
                {
                    jobId: job.id,
                },
            )
        } catch (error) {
            await this.jobActionService.failJob({
                job,
                error: `Failed to enqueue job to broker: ${error?.message ?? "unknown error"}`,
            })
            throw error
        }
        return job
    }
}

import type {
    EntityManager,
} from "typeorm"

/** Params for recomputing one enrollment's flashcard-course-stats projection row. */
export interface RecomputeUserFlashcardCourseStatsParams {
    /** The enrollment (user ├ù course) whose flashcard stats to rebuild. */
    enrollmentId: string
    /** Caller's transaction manager (inline write path); omit for the read path. */
    entityManager?: EntityManager
}

/** Params for reading one enrollment's flashcard-course stats. */
export interface UserFlashcardCourseStatsParams {
    /** The enrollment whose flashcard stats to read. */
    enrollmentId: string
}

/** One point on the quick-quiz coverage/XP trend line, oldest-of-the-recent-window first. */
export interface FlashcardQuizTrendPointData {
    /** When the session behind this point completed. */
    completedAt: Date
    /** The session's coverage, 0..1 (0 when never snapshotted). */
    coverage: number
    /** XP granted for the session. */
    xpEarned: number
}

/** One technology tag's aggregate quiz coverage across the scanned sessions. */
export interface FlashcardQuizTagStatData {
    /** The technology tag (e.g. "NestJS", "Redis"). */
    tag: string
    /** Aggregate coverage for this tag across every scanned session's cards carrying it, 0..1. */
    coverage: number
}

/** One "hard" quiz card ΓÇö a card the learner keeps under-answering (lowest per-card coverage), the quiz analogue of a review leech. */
export interface FlashcardQuizHardCardData {
    /** The card id (deep-link target). */
    cardId: string
    /** The card's question text (default-locale snapshot). */
    question: string
    /** Times this card was answered across the scanned quiz sessions (sample size). */
    attempts: number
    /** Times this card was answered with at least one blank wrong (coverage < 1). */
    wrongCount: number
    /** Aggregate coverage for this card = ╬úcorrectBlanks / ╬útotalBlanks across attempts, 0..1 (ranking key). */
    coverage: number
    /** Owning deck id (deep-link target). */
    deckId: string
    /** Owning deck title (default-locale snapshot). */
    deckTitle: string
}

/** One tag's most-recent weak-spot occurrence, carrying a study deep-link back to its source module/content. */
export interface FlashcardQuizWeakTagLinkData {
    /** The technology tag (e.g. "NestJS", "Redis"). */
    tag: string
    /** This tag's coverage on its most recent occurrence across the scanned sessions, 0..1. */
    coverage: number
    /** The single module this tag's cards map back to; null when the deck-to-module mapping was ambiguous. */
    moduleId: string | null
    /** The single content (lesson) this tag's cards map back to; null when the deck-to-content mapping was ambiguous. */
    contentId: string | null
}

/** One deck's aggregate quiz practice footprint across the scanned sessions. */
export interface FlashcardDeckStatData {
    /** The deck this aggregate is scoped to. */
    deckId: string
    /** The deck's title. */
    deckTitle: string
    /** Distinct scanned sessions that touched this deck (a deck answered twice in one session still counts once). */
    sessionCount: number
    /** Total card-answers (not unique cards) touching this deck across the scanned sessions. */
