@Injectable()
/**
 * CQRS projection service for a user's flashcard COURSE stats ΓÇö shared by both
 * the quick-quiz and review recap surfaces. The heavy scan/fold over
 * `flashcard_quiz_sessions` / `flashcard_review_sessions` / `flashcard_cards`
 * runs ONLY in {@link recompute} (the projector, triggered by CDC on both
 * source tables), building the aggregate jsonb. {@link getStats} reads the
 * flat row with a TTL lazy-refresh ΓÇö no per-request scan/fold.
 *
 * This mirrors what `MyFlashcardQuizStatsService.compute` and
 * `MyFlashcardReviewStatsService.compute`'s `computeByDeck` used to do inline
 * on every read (a bounded Γëñ50-row scan + GROUP BY) ΓÇö a violation of
 * `.claude/be/rules/cqrs-no-inline-aggregate.md` ("kß╗â cß║ú scale nhß╗Å").
 */
export class UserFlashcardCourseStatsProjectionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
    ) {}

    /**
     * Recompute + upsert the flashcard-course-stats aggregate for one
     * enrollment (idempotent).
     *
     * @param params - {@link RecomputeUserFlashcardCourseStatsParams}
     */
    async recompute(
        {
            enrollmentId,
            entityManager,
        }: RecomputeUserFlashcardCourseStatsParams,
    ): Promise<void> {
        // honour the caller's transaction when given, else the service connection
        const manager = entityManager ?? this.entityManager

        const {
            quizTrend,
            quizByTag,
            quizByDeck,
            weakTagLinks,
            quizHardCards,
            completedSessionCount,
            difficultyMix,
            conceptCoverage,
        } = await this.computeQuiz(manager,
            enrollmentId)
        const reviewByDeck = await this.computeReview(manager,
            enrollmentId)
        const {
            dueToday,
            dueForecast,
            masteryBreakdown,
            maturityLadder,
            forgetSoon,
        } = await this.computeDueAndMastery(manager,
            enrollmentId)
        const {
            leechCards,
            leechFocus,
            weakReviewTag,
            weakTags,
            matureRetention,
            youngRetention,
            reviewedTotal,
            courseRetention,
            bestReviewHour,
            deckRetention,
            retentionTrend,
        } = await this.computeReviewOutcome(manager,
            enrollmentId)

        const value: UserFlashcardCourseStatsResult = {
            quizTrend,
            quizByTag,
            quizByDeck,
            weakTagLinks,
            quizHardCards,
            completedSessionCount,
            difficultyMix,
            conceptCoverage,
            reviewByDeck,
            dueToday,
            dueForecast,
            masteryBreakdown,
            maturityLadder,
            forgetSoon,
            leechCards,
            leechFocus,
            weakReviewTag,
            weakTags,
            matureRetention,
            youngRetention,
            reviewedTotal,
            courseRetention,
            bestReviewHour,
            deckRetention,
            retentionTrend,
        }

        await manager.query(
            `INSERT INTO user_flashcard_course_stats_projections (enrollment_id, value)
             VALUES ($1::uuid, $2::jsonb)
             ON CONFLICT (enrollment_id) DO UPDATE SET
                 value      = EXCLUDED.value,
                 updated_at = now()`,
            [
                enrollmentId,
                JSON.stringify(value),
            ],
        )
    }

    /**
     * Read an enrollment's flashcard-course stats, TTL lazy-refreshed.
     *
     * @param params - {@link UserFlashcardCourseStatsParams}
     * @returns the stats (zeroed/empty when the enrollment has no history / row).
     */
    async getStats(
        {
            enrollmentId,
        }: UserFlashcardCourseStatsParams,
    ): Promise<UserFlashcardCourseStatsResult> {
        let row = await this.entityManager.findOne(
            UserFlashcardCourseStatsProjectionEntity,
            {
                where: {
                    enrollmentId,
                },
            },
        )
        // missing / past freshness window / SCHEMA-DRIFTED (a fresh row written
        // before the outcome fields existed lacks `leechCards` etc. ΓÇö recompute
        // once so those keys populate instead of reading as empty forever, thß║ºy
        // 2026-07-13: "sao kh├┤ng thß║Ñy leech/chart") ΓåÆ recompute + re-read.
        const missingOutcomeFields = row
            ? (() => {
                const value = row.value as Partial<UserFlashcardCourseStatsResult> | undefined
                // leechCards = review-outcome drift (2026-07-13); quizHardCards =
                // quiz-outcome drift (added later); maturityLadder = the
                // stats-insight-redesign drift (2026-07-17, this batch of new
                // fields); reviewedTotal = the course-scoped floor/hero drift
                // (2026-07-17, same day, added after maturityLadder shipped) ΓÇö
                // any absent means the row predates that fold, so recompute once
                // to populate it.
                return value?.leechCards === undefined
                    || value?.quizHardCards === undefined
                    || value?.maturityLadder === undefined
                    || value?.reviewedTotal === undefined
            })()
            : false
        if (!row || this.isStale(row.updatedAt) || missingOutcomeFields) {
            await this.recompute({
                enrollmentId,
            })
            row = await this.entityManager.findOne(
                UserFlashcardCourseStatsProjectionEntity,
                {
                    where: {
                        enrollmentId,
                    },
                },
            )
        }
        const value = row?.value as Partial<UserFlashcardCourseStatsResult> | undefined
        return {
            quizTrend: value?.quizTrend ?? [],
            quizByTag: value?.quizByTag ?? [],
            quizByDeck: value?.quizByDeck ?? [],
            weakTagLinks: value?.weakTagLinks ?? [],
            quizHardCards: value?.quizHardCards ?? [],
            completedSessionCount: value?.completedSessionCount ?? 0,
            difficultyMix: value?.difficultyMix ?? {
                junior: 0,
                middle: 0,
                senior: 0,
            },
            conceptCoverage: value?.conceptCoverage ?? null,
            reviewByDeck: value?.reviewByDeck ?? [],
            dueToday: value?.dueToday ?? 0,
            dueForecast: value?.dueForecast ?? [],
            masteryBreakdown: value?.masteryBreakdown ?? {
                mastered: 0,
                learning: 0,
                new: 0,
            },
            maturityLadder: value?.maturityLadder ?? {
                learning: 0,
                young: 0,
                mature: 0,
            },
            forgetSoon: value?.forgetSoon ?? {
                count: 0,
                horizonDays: DUE_FORECAST_DAYS,
                byDay: [],
            },
            leechCards: value?.leechCards ?? [],
            leechFocus: value?.leechFocus ?? [],
            weakReviewTag: value?.weakReviewTag ?? null,
            weakTags: value?.weakTags ?? [],
            matureRetention: value?.matureRetention ?? 0,
            youngRetention: value?.youngRetention ?? 0,
            reviewedTotal: value?.reviewedTotal ?? 0,
            courseRetention: value?.courseRetention ?? 0,
            bestReviewHour: value?.bestReviewHour ?? null,
            deckRetention: value?.deckRetention ?? [],
            retentionTrend: value?.retentionTrend ?? [],
        }
    }

    /**
     * The quick-quiz side of the aggregate ΓÇö trend/byTag/byDeck, COPIED
     * verbatim (parameterized by `enrollmentId`) from
     * `MyFlashcardQuizStatsService.compute`/`computeByTag`/`computeByDeck`.
     */
    private async computeQuiz(
        manager: EntityManager,
        enrollmentId: string,
    ): Promise<{
        quizTrend: Array<FlashcardQuizTrendPointData>
        quizByTag: Array<FlashcardQuizTagStatData>
        quizByDeck: Array<FlashcardDeckStatData>
        weakTagLinks: Array<FlashcardQuizWeakTagLinkData>
        quizHardCards: Array<FlashcardQuizHardCardData>
        completedSessionCount: number
        difficultyMix: FlashcardDifficultyMixData
        conceptCoverage: FlashcardConceptCoverageData | null
    }> {
        const sessions = await manager.find(
            FlashcardQuizSessionEntity,
            {
                where: {
                    enrollment: {
                        id: enrollmentId,
                    },
                    status: "completed",
                },
                order: {
                    updatedAt: "DESC",
                },
                take: STATS_SESSION_SCAN_CAP,
            },
        )

        const weakTagLinks = this.computeWeakTagLinks(sessions)
        const completedSessionCount = sessions.length
        const difficultyMix = this.computeDifficultyMix(sessions)

        // `sessions` is newest-first (DESC); reverse to oldest-first, then take
        // the last N of that ascending list ΓÇö i.e. the most recent N sessions,
        // oldest-of-those-first, which is what a left-to-right trend line wants
        const quizTrend = [...sessions]
            .reverse()
            .slice(-STATS_TREND_LENGTH)
            .map((session) => ({
                completedAt: session.updatedAt,
                coverage: session.coverage ?? 0,
                xpEarned: session.xpEarned,
            }))

        // gather the distinct cardIds referenced across every scanned
        // session's per-card results, so the card/tag/deck lookup below is
        // ONE query rather than N+1
        const cardIds = [...new Set(
            sessions.flatMap((session) => (session.results ?? []).map((result) => result.cardId)),
        )]

        if (cardIds.length === 0) {
            return {
                quizTrend,
                quizByTag: [],
                quizByDeck: [],
                weakTagLinks,
                quizHardCards: [],
                completedSessionCount,
                difficultyMix,
                conceptCoverage: await this.computeConceptCoverage(manager,
                    enrollmentId,
                    new Set()),
            }
        }

        // ONE query for both the tag breakdown and the deck breakdown ΓÇö avoids
        // querying FlashcardCardEntity twice
        const cards = await manager.find(
            FlashcardCardEntity,
            {
                where: {
                    id: In(cardIds),
                },
                relations: {
                    deck: true,
                },
                // NO `deckId` here: it is a virtual `@RelationId` on
                // FlashcardCardEntity, and TypeORM's find `select` only accepts real
                // columns/relations ΓÇö listing it throws EntityPropertyNotFoundError
                // ("Property \"deckId\" was not found in \"FlashcardCardEntity\"") at
                // RUNTIME, which killed `recompute()` on its FIRST fold (computeQuiz)
                // and so silently left EVERY flashcard course-stat empty since
                // b0c780f4. Nothing reads `card.deckId` here anyway ΓÇö the deck comes
                // from the `deck` relation below (2026-07-17 fix).
                select: {
                    id: true,
                    question: true,
                    tags: true,
                    deck: {
                        id: true,
                        title: true,
                    },
                },
            },
        )
        const cardById = new Map(cards.map((card) => [
            card.id,
            card,
        ]))

        const quizByTag = this.computeByTag(sessions,
            cardById)
        const quizByDeck = await this.computeByDeck(manager,
            sessions,
            cardById)
        const quizHardCards = this.computeQuizHardCards(sessions,
            cardById)
        // distinct tags actually attempted = every tag on every scanned card,
        // straight off the same `cards` fetch above (no extra query)
        const attemptedTags = new Set(cards.flatMap((card) => card.tags))
        const conceptCoverage = await this.computeConceptCoverage(manager,
            enrollmentId,
            attemptedTags)

        return {
            quizTrend,
            quizByTag,
            quizByDeck,
            weakTagLinks,
            quizHardCards,
            completedSessionCount,
            difficultyMix,
            conceptCoverage,
        }
    }

    /**
     * Bucket completed quiz sessions by their `level` filter ΓÇö Staff folds
     * into `senior` (the FE only shows 3 difficulty buckets) and sessions
     * drawn with NO level filter ("all levels") are excluded, since they
     * can't be attributed to a single difficulty.
     */
    private computeDifficultyMix(
        sessions: Array<FlashcardQuizSessionEntity>,
    ): FlashcardDifficultyMixData {
        const mix: FlashcardDifficultyMixData = {
            junior: 0,
            middle: 0,
            senior: 0,
        }
        for (const session of sessions) {
            switch (session.level) {
            case "junior":
                mix.junior += 1
                break
            case "middle":
                mix.middle += 1
                break
            case "senior":
            case "staff":
                mix.senior += 1
                break
            default:
                // null ("all levels") ΓÇö not attributable to one bucket, skip
                break
            }
        }
        return mix
    }

    /**
     * How many of the course's technology tags the learner has attempted vs
     * how many exist ΓÇö `total` is a real `COUNT(DISTINCT tag)` over the
     * course's decks (cheap: one query, mirrors the `totalCardsRow` pattern in
     * {@link computeDueAndMastery}), not the byTag-length approximation the
     * spec allows as a fallback. Null only when the course itself has no tag
     * data to compare against (guards a divide-by-zero on the FE).
     */
    private async computeConceptCoverage(
        manager: EntityManager,
        enrollmentId: string,
        attemptedTags: Set<string>,
    ): Promise<FlashcardConceptCoverageData | null> {
        const [row] = await manager.query<Array<CourseTagCountRow>>(
            `SELECT COUNT(DISTINCT tag.value)::text AS total
             FROM flashcard_cards card
             JOIN flashcard_decks deck ON deck.id = card.flashcard_deck_id
             JOIN enrollments enrollment ON enrollment.course_id = deck.course_id
             CROSS JOIN LATERAL jsonb_array_elements_text(card.tags) AS tag(value)
             WHERE enrollment.id = $1`,
            [
                enrollmentId,
            ],
        )
        const total = Number(row?.total) || 0
        if (total === 0) {
            return null
        }
        return {
            covered: attemptedTags.size,
            total,
        }
    }

    /**
     * The quiz OUTCOME diagnosis (thß║ºy 2026-07-13 quiz-stats redesign ΓÇö dß║½n bß║▒ng
     * lß╗ù hß╗òng, not vanity) ΓÇö the "c├óu hay sai" list, the quiz analogue of a review
     * leech. Folds each (session, result) pair from `results[]` per card:
     * aggregate coverage = ╬úcorrectBlanks / ╬útotalBlanks, `attempts` = times
     * answered, `wrongCount` = attempts with any blank missed (coverage < 1). Only
     * cards answered >= {@link QUIZ_HARD_CARD_MIN_ATTEMPTS} times qualify (avoid a
     * 1-off miss), ranked lowest coverage first, capped at
     * {@link QUIZ_HARD_CARD_LIMIT}. Derived from the same in-memory `sessions` +
     * `cardById` the tag/deck folds use ΓÇö no extra query.
     */
    private computeQuizHardCards(
        sessions: Array<FlashcardQuizSessionEntity>,
        cardById: Map<string, FlashcardCardEntity>,
    ): Array<FlashcardQuizHardCardData> {
        const correctByCard = new Map<string, number>()
        const totalByCard = new Map<string, number>()
        const attemptsByCard = new Map<string, number>()
        const wrongByCard = new Map<string, number>()

        for (const session of sessions) {
            for (const result of session.results ?? []) {
                if (!cardById.has(result.cardId)) {
                    // card id not found (deleted / bad input) ΓÇö skip silently
                    continue
                }
                const total = Math.max(0,
                    Math.trunc(result.totalBlanks))
                const correct = Math.max(0,
                    Math.min(Math.trunc(result.correctBlanks),
                        total))
                correctByCard.set(result.cardId,
                    (correctByCard.get(result.cardId) ?? 0) + correct)
                totalByCard.set(result.cardId,
                    (totalByCard.get(result.cardId) ?? 0) + total)
                attemptsByCard.set(result.cardId,
                    (attemptsByCard.get(result.cardId) ?? 0) + 1)
                if (correct < total) {
                    wrongByCard.set(result.cardId,
                        (wrongByCard.get(result.cardId) ?? 0) + 1)
                }
            }
        }

        return [...attemptsByCard.entries()]
            .filter(([, attempts]) => attempts >= QUIZ_HARD_CARD_MIN_ATTEMPTS)
            .map(([cardId]) => {
                const card = cardById.get(cardId)
                const total = totalByCard.get(cardId) ?? 0
                return {
                    cardId,
                    question: card?.question ?? "",
                    attempts: attemptsByCard.get(cardId) ?? 0,
                    wrongCount: wrongByCard.get(cardId) ?? 0,
                    coverage: total === 0 ? 0 : (correctByCard.get(cardId) ?? 0) / total,
                    deckId: card?.deckId ?? "",
                    deckTitle: card?.deck?.title ?? "",
                }
            })
            .sort((prev, next) => prev.coverage - next.coverage || next.wrongCount - prev.wrongCount)
            .slice(0,
                QUIZ_HARD_CARD_LIMIT)
    }

    /** One per-card result's own correct/total ratio, guarding against a zero denominator. */
    private resultCoverage(result: FlashcardQuizSessionResult): number {
        const total = Math.max(0,
            Math.trunc(result.totalBlanks))
        if (total === 0) {
            return 0
        }
        const correct = Math.max(0,
            Math.min(Math.trunc(result.correctBlanks),
                total))
        return correct / total
    }

    /**
     * Accumulate per-tag correct/total across every (session, result) pair,
     * ranked by coverage descending and capped at {@link STATS_MAX_TAGS}.
     */
    private computeByTag(
        sessions: Array<FlashcardQuizSessionEntity>,
        cardById: Map<string, FlashcardCardEntity>,
    ): Array<FlashcardQuizTagStatData> {
        const correctByTag = new Map<string, number>()
        const totalByTag = new Map<string, number>()
        for (const session of sessions) {
            for (const result of session.results ?? []) {
                const card = cardById.get(result.cardId)
                if (!card) {
                    // card id not found (deleted / bad input) ΓÇö skip silently
                    continue
                }
                const coverage = this.resultCoverage(result)
                for (const tag of card.tags) {
                    correctByTag.set(tag,
                        (correctByTag.get(tag) ?? 0) + coverage)
                    totalByTag.set(tag,
                        (totalByTag.get(tag) ?? 0) + 1)
                }
            }
        }

        return [...totalByTag.entries()]
            .map(([
                tag,
                total,
            ]) => ({
                tag,
                coverage: total === 0 ? 0 : (correctByTag.get(tag) ?? 0) / total,
            }))
            .sort((prev, next) => next.coverage - prev.coverage)
            .slice(0,
                STATS_MAX_TAGS)
    }

    /**
     * Derive the weakest-tags-with-a-study-link list from each session's
     * already-snapshotted `weakTags` (no re-derivation from `results[]`) ΓÇö
     * walks `sessions` in their existing DESC (newest-first) order and keeps
     * ONLY the first (i.e. most recent) occurrence of each tag, then sorts
     * the kept occurrences by coverage ascending (weakest first), capped at
     * {@link STATS_MAX_TAGS}.
     */
    private computeWeakTagLinks(
        sessions: Array<FlashcardQuizSessionEntity>,
    ): Array<FlashcardQuizWeakTagLinkData> {
        const linkByTag = new Map<string, FlashcardQuizWeakTagLinkData>()
        for (const session of sessions) {
            for (const weakTag of session.weakTags ?? []) {
                if (linkByTag.has(weakTag.tag)) {
                    // already recorded this tag's MOST RECENT occurrence
                    // (sessions are newest-first) ΓÇö skip older occurrences
                    continue
                }
                linkByTag.set(weakTag.tag,
                    this.toWeakTagLink(weakTag))
            }
        }

        return [...linkByTag.values()]
            .sort((prev, next) => prev.coverage - next.coverage)
            .slice(0,
                STATS_MAX_TAGS)
    }

    /** Normalize one session-snapshotted weak tag into the projection's link shape (undefined ΓåÆ null). */
    private toWeakTagLink(
        weakTag: FlashcardQuizSessionWeakTag,
    ): FlashcardQuizWeakTagLinkData {
        return {
            tag: weakTag.tag,
            coverage: weakTag.coverage,
            moduleId: weakTag.moduleId ?? null,
            contentId: weakTag.contentId ?? null,
        }
    }

    /**
     * Accumulate per-deck distinct-session touches + card-answer counts
     * across every scanned session, then resolve each touched deck's total
     * card count in one groupBy query.
     */
    private async computeByDeck(
        manager: EntityManager,
        sessions: Array<FlashcardQuizSessionEntity>,
        cardById: Map<string, FlashcardCardEntity>,
    ): Promise<Array<FlashcardDeckStatData>> {
        const sessionIdsByDeck = new Map<string, Set<string>>()
        const cardsAnsweredByDeck = new Map<string, number>()
        const deckTitleById = new Map<string, string>()

        for (const session of sessions) {
            for (const result of session.results ?? []) {
                const card = cardById.get(result.cardId)
                if (!card?.deck) {
                    continue
                }
                const deckId = card.deckId
                if (!sessionIdsByDeck.has(deckId)) {
                    sessionIdsByDeck.set(deckId,
                        new Set())
                }
                // a Set, so a deck answered twice in one session still counts as 1 session
                sessionIdsByDeck.get(deckId)?.add(session.id)
                cardsAnsweredByDeck.set(deckId,
                    (cardsAnsweredByDeck.get(deckId) ?? 0) + 1)
                deckTitleById.set(deckId,
                    card.deck.title)
            }
        }

        const deckIds = [...sessionIdsByDeck.keys()]
        if (deckIds.length === 0) {
            return []
        }

        // single groupBy query for every touched deck's total card count
        const totalRows = await manager
            .createQueryBuilder(FlashcardCardEntity,
                "card")
            .select("card.flashcard_deck_id",
                "deckId")
            .addSelect("COUNT(*)",
                "total")
            .where("card.flashcard_deck_id IN (:...deckIds)",
                {
                    deckIds,
                })
            .groupBy("card.flashcard_deck_id")
            .getRawMany<DeckCardCountRow>()
        const totalCardsByDeck = new Map(totalRows.map((row) => [
            row.deckId,
            Number(row.total) || 0,
        ]))

        return deckIds.map((deckId) => ({
            deckId,
            deckTitle: deckTitleById.get(deckId) ?? "",
            sessionCount: sessionIdsByDeck.get(deckId)?.size ?? 0,
            cardsAnswered: cardsAnsweredByDeck.get(deckId) ?? 0,
            totalCards: totalCardsByDeck.get(deckId) ?? 0,
        }))
    }

    /**
     * The review side of the aggregate ΓÇö `reviewByDeck`, COPIED verbatim
     * (parameterized by `enrollmentId`) from
     * `MyFlashcardReviewStatsService.computeByDeck`.
     */
    private async computeReview(
        manager: EntityManager,
        enrollmentId: string,
    ): Promise<Array<FlashcardReviewDeckStatData>> {
        const sessions = await manager.find(
            FlashcardReviewSessionEntity,
            {
                where: {
                    enrollment: {
                        id: enrollmentId,
                    },
                    status: "completed",
                },
                relations: {
                    deck: true,
                },
                order: {
                    updatedAt: "DESC",
                },
                take: STATS_SESSION_SCAN_CAP,
            },
        )

        if (sessions.length === 0) {
            return []
        }

        const sessionCountByDeck = new Map<string, number>()
        const cardsReviewedByDeck = new Map<string, number>()
        const deckTitleById = new Map<string, string>()

        for (const session of sessions) {
            const deckId = session.deckId
            sessionCountByDeck.set(deckId,
                (sessionCountByDeck.get(deckId) ?? 0) + 1)
            cardsReviewedByDeck.set(deckId,
                (cardsReviewedByDeck.get(deckId) ?? 0) + session.reviewedCount)
            if (session.deck) {
                deckTitleById.set(deckId,
                    session.deck.title)
            }
        }

        const deckIds = [...sessionCountByDeck.keys()]
        if (deckIds.length === 0) {
            return []
        }

        // single groupBy query for every touched deck's total card count
        const totalRows = await manager
            .createQueryBuilder(FlashcardCardEntity,
                "card")
            .select("card.flashcard_deck_id",
                "deckId")
            .addSelect("COUNT(*)",
                "total")
            .where("card.flashcard_deck_id IN (:...deckIds)",
                {
                    deckIds,
                })
            .groupBy("card.flashcard_deck_id")
            .getRawMany<DeckCardCountRow>()
        const totalCardsByDeck = new Map(totalRows.map((row) => [
            row.deckId,
            Number(row.total) || 0,
        ]))

        return deckIds.map((deckId) => ({
            deckId,
            deckTitle: deckTitleById.get(deckId) ?? "",
            sessionCount: sessionCountByDeck.get(deckId) ?? 0,
            cardsReviewed: cardsReviewedByDeck.get(deckId) ?? 0,
            totalCards: totalCardsByDeck.get(deckId) ?? 0,
        }))
    }

    /**
     * The due/mastery side of the aggregate ΓÇö `dueToday`/`dueForecast`/
     * `masteryBreakdown`/`maturityLadder`/`forgetSoon`, all scoped to this
     * enrollment via `user_flashcard_reviews.enrollment_id` (+ the
     * enrollment's course for `totalCards`). Small raw aggregates, run ONLY
     * here (never per-request).
     */
    private async computeDueAndMastery(
        manager: EntityManager,
        enrollmentId: string,
    ): Promise<{
        dueToday: number
        dueForecast: Array<FlashcardDueForecastPointData>
        masteryBreakdown: FlashcardMasteryBreakdownData
        maturityLadder: FlashcardMaturityLadderData
        forgetSoon: FlashcardForgetSoonData
    }> {
        // 1. cards due right now
        const [dueTodayRow] = await manager.query<Array<DueTodayRow>>(
            `SELECT COUNT(*)::text AS count
             FROM user_flashcard_reviews
             WHERE enrollment_id = $1
               AND due_at <= now()`,
            [
                enrollmentId,
            ],
        )
        const dueToday = Number(dueTodayRow?.count) || 0

        // 2. cards due per VN-day over the next DUE_FORECAST_DAYS days ΓÇö
        // grouped in SQL, zero-filled in JS (mirrors `foldDailyCounts` in
        // `UserFlashcardStatsProjectionService`)
        const forecastRows = await manager.query<Array<DueForecastRow>>(
            `SELECT (due_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date::text AS day,
                    COUNT(*)::text AS count
             FROM user_flashcard_reviews
             WHERE enrollment_id = $1
               AND due_at > now()
               AND due_at <= now() + interval '7 days'
             GROUP BY day`,
            [
                enrollmentId,
            ],
        )
        const forecastCountByDay = new Map(forecastRows.map((row) => [
            row.day,
            Number(row.count) || 0,
        ]))
        const [todayRow] = await manager.query<Array<VnTodayRow>>(
            "SELECT (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date::text AS today",
        )
        const [
            year,
            month,
            day,
        ] = todayRow.today.split("-").map(Number)
        const anchor = Date.UTC(year,
            month - 1,
            day)
        const dueForecast: Array<FlashcardDueForecastPointData> = []
        for (let offset = 1; offset <= DUE_FORECAST_DAYS; offset += 1) {
            const date = new Date(anchor + offset * MS_PER_DAY).toISOString().slice(0,
                10)
            dueForecast.push({
                date,
                count: forecastCountByDay.get(date) ?? 0,
            })
        }

        // 3. reviewed/mastered tally on this enrollment's reviews
        const [masteryRow] = await manager.query<Array<MasteryRow>>(
            `SELECT COUNT(*)::text AS "reviewedTotal",
                    COUNT(*) FILTER (WHERE repetitions >= ${MASTERED_REPETITIONS})::text AS mastered
             FROM user_flashcard_reviews
             WHERE enrollment_id = $1`,
            [
                enrollmentId,
            ],
        )
        const reviewedTotal = Number(masteryRow?.reviewedTotal) || 0
        const mastered = Number(masteryRow?.mastered) || 0

        // this enrollment's course's total card count (across every deck)
        const [totalCardsRow] = await manager.query<Array<TotalCardsRow>>(
            `SELECT COUNT(*)::text AS total
             FROM flashcard_cards card
             JOIN flashcard_decks deck ON deck.id = card.flashcard_deck_id
             JOIN enrollments enrollment ON enrollment.course_id = deck.course_id
             WHERE enrollment.id = $1`,
            [
                enrollmentId,
            ],
        )
        const totalCards = Number(totalCardsRow?.total) || 0

        // 4. maturity LADDER ΓÇö a coarser, interval_days-based 3-way cut
        // (learning/young/mature) than the repetitions-based masteryBreakdown
        // above; "never reviewed" cards fold into `learning` (thß║ºy 2026-07-17:
        // "chß╗ë 8% ch├¡n = tiß║┐n ─æß╗Ö THß║¼T").
        const [ladderRow] = await manager.query<Array<MaturityLadderRow>>(
            `SELECT COUNT(*) FILTER (WHERE interval_days < 1)::text AS learning,
                    COUNT(*) FILTER (WHERE interval_days >= 1 AND interval_days <= ${MATURITY_LADDER_YOUNG_MAX_DAYS})::text AS young,
                    COUNT(*) FILTER (WHERE interval_days > ${MATURITY_LADDER_YOUNG_MAX_DAYS})::text AS mature
             FROM user_flashcard_reviews
             WHERE enrollment_id = $1`,
            [
                enrollmentId,
            ],
        )
        const neverReviewed = Math.max(0,
            totalCards - reviewedTotal)
        const maturityLadder: FlashcardMaturityLadderData = {
            learning: (Number(ladderRow?.learning) || 0) + neverReviewed,
            young: Number(ladderRow?.young) || 0,
            mature: Number(ladderRow?.mature) || 0,
        }

        // 5. forget SOON ΓÇö same 7-day-forward series as `dueForecast` (no
        // extra query), just a leading-window sum for the "sß║╜ qu├¬n sß╗¢m" headline.
        const forgetSoon: FlashcardForgetSoonData = {
            count: dueForecast
                .slice(0,
                    FORGET_SOON_HEADLINE_DAYS)
                .reduce((sum, point) => sum + point.count,
                    0),
            horizonDays: DUE_FORECAST_DAYS,
            byDay: dueForecast,
        }

        return {
            dueToday,
            dueForecast,
            masteryBreakdown: {
                mastered,
                learning: reviewedTotal - mastered,
                new: neverReviewed,
            },
            maturityLadder,
            forgetSoon,
        }
    }

    /**
     * The review-OUTCOME side of the aggregate (thß║ºy 2026-07-13 "thß╗æng k├¬ v├┤
     * ngh─⌐a qu├í, render lß║íi" ΓÇö dß║½n bß║▒ng viß╗çc-Cß║ªN-Sß╗¼A, not vanity effort): the
     * outcome aggregates that turn the stats tab into a fix-funnel ΓÇö
     * `leechCards`/`leechFocus` (kept forgetting), `weakReviewTag`/`weakTags`
     * (worst-retention tag(s)), `deckRetention` (outcome per deck vs the
     * footprint `reviewByDeck`), `retentionTrend` ("─æang cß║úi thiß╗çn?"), the
     * mature-vs-young retention split, and `bestReviewHour`. All derived from
     * `flashcard_review_events` (the SM-2 grade log) joined to the
     * enrollment's course cards ΓÇö scoped to this enrollment's USER (events
     * are user-keyed) and COURSE (card ΓåÆ deck ΓåÆ course), and folded HERE only
     * (CDC-triggered), never per-request
     * (`.claude/be/rules/cqrs-no-inline-aggregate.md`). `recalled` = grade >=
     * {@link RECALLED_GRADE}; retention = recalled/total ├ù 100.
     */
    private async computeReviewOutcome(
        manager: EntityManager,
        enrollmentId: string,
    ): Promise<{
        leechCards: Array<FlashcardLeechCardData>
        leechFocus: Array<FlashcardLeechFocusCardData>
        weakReviewTag: FlashcardWeakReviewTagData | null
        weakTags: Array<FlashcardWeakTagData>
        matureRetention: number
        youngRetention: number
        reviewedTotal: number
        courseRetention: number
        bestReviewHour: FlashcardBestReviewHourData | null
        deckRetention: Array<FlashcardDeckRetentionData>
        retentionTrend: Array<FlashcardRetentionTrendPointData>
    }> {
        // Shared scope: this enrollment's own user's events on THIS course's cards.
        // `enrollments en` resolves both the user (event owner) and the course
        // (deck filter) from the single enrollment id, so every query below joins
        // events Γïê cards Γïê decks Γïê enrollment without leaking another user's grades.
        const scopeJoin = `
            FROM flashcard_review_events e
            JOIN enrollments en ON en.id = $1 AND e.user_id = en.user_id
            JOIN flashcard_cards card ON card.id = e.flashcard_card_id
            JOIN flashcard_decks deck ON deck.id = card.flashcard_deck_id AND deck.course_id = en.course_id`

        // 1. LEECH ΓÇö cards graded Again the most (>= LEECH_MIN_AGAIN times), top LEECH_LIMIT.
        const leechRows = await manager.query<Array<LeechCardRow>>(
            `SELECT card.id AS card_id,
                    card.question AS question,
                    COUNT(*) FILTER (WHERE e.grade = 0)::text AS forgot_count,
                    deck.id AS deck_id,
                    deck.title AS deck_title
             ${scopeJoin}
             GROUP BY card.id, card.question, deck.id, deck.title
             HAVING COUNT(*) FILTER (WHERE e.grade = 0) >= ${LEECH_MIN_AGAIN}
             ORDER BY forgot_count DESC, card.id ASC
             LIMIT ${LEECH_LIMIT}`,
            [
                enrollmentId,
            ],
        )
        const leechCards: Array<FlashcardLeechCardData> = leechRows.map((row) => ({
            cardId: row.card_id,
            question: row.question ?? "",
            forgotCount: Number(row.forgot_count) || 0,
            deckId: row.deck_id,
            deckTitle: row.deck_title ?? "",
        }))

        // 2. WEAK TAGS ΓÇö EVERY tag's retention with >= WEAK_TAG_MIN_SAMPLE graded
        // reviews, worst-first (thß║ºy 2026-07-17: "bß╗Å LIMIT 1" ΓÇö the old query
        // only ever surfaced the single worst tag; `weakReviewTag` below is now
        // just this same list's head, no second query). `card.tags` is a jsonb
        // string array ΓåÆ unnest with jsonb_array_elements_text.
        const tagRows = await manager.query<Array<TagRetentionWithCardCountRow>>(
            `SELECT tag.value AS tag,
                    COUNT(*) FILTER (WHERE e.grade >= ${RECALLED_GRADE})::text AS recalled,
                    COUNT(*)::text AS total,
                    COUNT(DISTINCT card.id)::text AS card_count
             ${scopeJoin}
             CROSS JOIN LATERAL jsonb_array_elements_text(card.tags) AS tag(value)
             GROUP BY tag.value
             HAVING COUNT(*) >= ${WEAK_TAG_MIN_SAMPLE}
             ORDER BY (COUNT(*) FILTER (WHERE e.grade >= ${RECALLED_GRADE})::float / COUNT(*)) ASC,
                      total DESC`,
            [
                enrollmentId,
            ],
        )
        const weakTags: Array<FlashcardWeakTagData> = tagRows.map((row) => ({
            tag: row.tag,
            retention: this.retentionPercent(row.recalled,
                row.total),
            cardCount: Number(row.card_count) || 0,
        }))
        const weakReviewTag: FlashcardWeakReviewTagData | null = tagRows.length > 0
            ? {
                tag: tagRows[0].tag,
                retention: this.retentionPercent(tagRows[0].recalled,
                    tagRows[0].total),
                reviewCount: Number(tagRows[0].total) || 0,
            }
            : null

        // 3. DECK RETENTION ΓÇö recalled/total per deck, weakest first (outcome, not footprint).
        const deckRows = await manager.query<Array<DeckRetentionRow>>(
            `SELECT deck.id AS deck_id,
                    deck.title AS deck_title,
                    COUNT(*) FILTER (WHERE e.grade >= ${RECALLED_GRADE})::text AS recalled,
                    COUNT(*)::text AS total
             ${scopeJoin}
             GROUP BY deck.id, deck.title
             ORDER BY (COUNT(*) FILTER (WHERE e.grade >= ${RECALLED_GRADE})::float / COUNT(*)) ASC,
                      total DESC`,
            [
                enrollmentId,
            ],
        )
        const deckRetention: Array<FlashcardDeckRetentionData> = deckRows.map((row) => ({
            deckId: row.deck_id,
            deckTitle: row.deck_title ?? "",
            retention: this.retentionPercent(row.recalled,
                row.total),
            reviewCount: Number(row.total) || 0,
        }))

        // 4. RETENTION TREND ΓÇö recalled/total per VN-day over the trailing window,
        // only days WITH reviews (the FE line skips gaps), most-recent last.
        const trendRows = await manager.query<Array<RetentionTrendRow>>(
            `SELECT (e.reviewed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date::text AS day,
                    COUNT(*) FILTER (WHERE e.grade >= ${RECALLED_GRADE})::text AS recalled,
                    COUNT(*)::text AS total
             ${scopeJoin}
             AND e.reviewed_at >= now() - interval '${RETENTION_TREND_DAYS} days'
             GROUP BY day
             ORDER BY day ASC`,
            [
                enrollmentId,
            ],
        )
        const retentionTrend: Array<FlashcardRetentionTrendPointData> = trendRows.map((row) => ({
            date: row.day,
            retention: this.retentionPercent(row.recalled,
                row.total),
            reviewCount: Number(row.total) || 0,
        }))

        // 5. MATURE vs YOUNG retention ΓÇö is forgetting concentrated on freshly-seen
        // cards (young, still spacing out) or on stuff already committed (mature)?
        // Joins the event log to the CURRENT `user_flashcard_reviews.interval_days`
        // (an approximation: buckets by the card's interval NOW, not at each past
        // event's time ΓÇö cheap and stable enough for a "where's the problem" split).
        const [maturityRetentionRow] = await manager.query<Array<MaturityRetentionRow>>(
            `SELECT COUNT(*) FILTER (WHERE r.interval_days >= ${RETENTION_MATURE_THRESHOLD_DAYS} AND e.grade >= ${RECALLED_GRADE})::text AS "matureRecalled",
                    COUNT(*) FILTER (WHERE r.interval_days >= ${RETENTION_MATURE_THRESHOLD_DAYS})::text AS "matureTotal",
                    COUNT(*) FILTER (WHERE r.interval_days < ${RETENTION_MATURE_THRESHOLD_DAYS} AND e.grade >= ${RECALLED_GRADE})::text AS "youngRecalled",
                    COUNT(*) FILTER (WHERE r.interval_days < ${RETENTION_MATURE_THRESHOLD_DAYS})::text AS "youngTotal"
             ${scopeJoin}
             JOIN user_flashcard_reviews r ON r.flashcard_card_id = card.id AND r.enrollment_id = en.id`,
            [
                enrollmentId,
            ],
        )
        const matureRetention = this.retentionPercent(
            maturityRetentionRow?.matureRecalled ?? "0",
            maturityRetentionRow?.matureTotal ?? "0",
        )
        const youngRetention = this.retentionPercent(
            maturityRetentionRow?.youngRecalled ?? "0",
            maturityRetentionRow?.youngTotal ?? "0",
        )
        // COURSE-SCOPED review volume + retention ΓÇö the mature/young split above
        // already scanned exactly this course's graded events, so summing its two
        // buckets costs no extra query. These are what the "Thß╗æng k├¬" tab's floor +
        // memory-health hero must read: the per-USER lifetime `totalReviewed`/
        // `retentionRate` blend every course together, which is wrong for a
        // course-scoped tab (2026-07-17).
        const reviewedTotal = (Number(maturityRetentionRow?.matureTotal) || 0)
            + (Number(maturityRetentionRow?.youngTotal) || 0)
        const courseRetention = this.retentionPercent(
            String((Number(maturityRetentionRow?.matureRecalled) || 0)
                + (Number(maturityRetentionRow?.youngRecalled) || 0)),
            String(reviewedTotal),
        )

        // 6. LEECH FOCUS ΓÇö reason-tagged rewrite list: `lapsed` = graded Again
        // AFTER at least one prior Good/Easy on the SAME card (learned it once,
        // then forgot); `stuckHard` = repeatedly graded Hard (never forgets
        // outright, never firms up either). The window function looks ONLY at
        // rows strictly BEFORE the current one (`ROWS BETWEEN UNBOUNDED
        // PRECEDING AND 1 PRECEDING`) so "prior recall" never counts the
        // current grade against itself.
        const leechFocusRows = await manager.query<Array<LeechFocusRow>>(
            `WITH events AS (
                 SELECT card.id AS card_id,
                        card.question AS question,
                        deck.id AS deck_id,
                        deck.title AS deck_title,
                        e.grade,
                        MAX(CASE WHEN e.grade >= ${RECALLED_GRADE} THEN 1 ELSE 0 END) OVER (
                            PARTITION BY card.id
                            ORDER BY e.reviewed_at
                            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                        ) AS had_prior_recall
                 ${scopeJoin}
             ),
             tally AS (
                 SELECT card_id, question, deck_id, deck_title,
                        COUNT(*) FILTER (WHERE grade = 0 AND had_prior_recall = 1) AS lapsed_count,
                        COUNT(*) FILTER (WHERE grade = 1) AS hard_count
                 FROM events
                 GROUP BY card_id, question, deck_id, deck_title
             )
             SELECT card_id, question, deck_id, deck_title,
                    lapsed_count::text AS lapsed_count,
                    hard_count::text AS hard_count
             FROM tally
             WHERE lapsed_count > 0 OR hard_count >= ${STUCK_HARD_MIN_COUNT}
             ORDER BY GREATEST(lapsed_count, hard_count) DESC, card_id ASC
             LIMIT ${LEECH_FOCUS_LIMIT}`,
            [
                enrollmentId,
            ],
        )
        const leechFocus: Array<FlashcardLeechFocusCardData> = leechFocusRows.map((row) => {
            const lapsedCount = Number(row.lapsed_count) || 0
            const hardCount = Number(row.hard_count) || 0
            // lapsed takes priority ΓÇö "learned it once, then forgot" is the
            // sharper signal than "keeps grading Hard"
            const reason: "lapsed" | "stuckHard" = lapsedCount > 0 ? "lapsed" : "stuckHard"
            return {
                cardId: row.card_id,
                question: row.question ?? "",
                deckId: row.deck_id,
                deckTitle: row.deck_title ?? "",
                lapseCount: reason === "lapsed" ? lapsedCount : hardCount,
                reason,
            }
        })

        // 7. BEST REVIEW HOUR ΓÇö the hour-of-day (VN time) with the best
        // retention, guarded by BEST_HOUR_MIN_SAMPLE so a single lucky review
        // at 3am can't "win".
        const [bestHourRow] = await manager.query<Array<BestHourRow>>(
            `SELECT EXTRACT(HOUR FROM e.reviewed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::int AS hour,
                    COUNT(*) FILTER (WHERE e.grade >= ${RECALLED_GRADE})::text AS recalled,
                    COUNT(*)::text AS total
             ${scopeJoin}
             GROUP BY hour
             HAVING COUNT(*) >= ${BEST_HOUR_MIN_SAMPLE}
             ORDER BY (COUNT(*) FILTER (WHERE e.grade >= ${RECALLED_GRADE})::float / COUNT(*)) DESC,
                      total DESC
             LIMIT 1`,
            [
                enrollmentId,
            ],
        )
        const bestReviewHour: FlashcardBestReviewHourData | null = bestHourRow
            ? {
                hour: bestHourRow.hour,
                retention: this.retentionPercent(bestHourRow.recalled,
                    bestHourRow.total),
            }
            : null

        return {
            leechCards,
            leechFocus,
            weakReviewTag,
            weakTags,
            matureRetention,
            youngRetention,
            reviewedTotal,
            courseRetention,
            bestReviewHour,
            deckRetention,
            retentionTrend,
        }
    }

    /** recalled/total as an integer percent 0..100, guarding a zero denominator. */
    private retentionPercent(recalled: string, total: string): number {
        const totalNum = Number(total) || 0
        if (totalNum === 0) {
            return 0
        }
        return Math.round(((Number(recalled) || 0) / totalNum) * 100)
    }

    /**
     * Whether a projection row is past its freshness window.
     *
     * @param updatedAt - the row's last write time.
     * @returns true when older than the configured TTL.
     */
    private isStale(updatedAt: Date): boolean {
        return Date.now() - updatedAt.getTime() > envConfig().projection.staleAfterMs
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    In,
} from "typeorm"
import {
    FlashcardLevel,
    InjectPrimaryPostgreSQLEntityManager,
    MockInterviewAttemptEntity,
    MockInterviewPhase,
    MockInterviewSessionEntity,
    UserMockInterviewCourseStatsProjectionEntity,
} from "@modules/databases"
import {
    envConfig,
} from "@modules/env"
import {
    toUnknownRecordArray,
} from "@modules/common"
import type {
    MockInterviewCourseStatsBreakdownItemData,
    MockInterviewCourseStatsRecurringGapData,
    MockInterviewCourseStatsTrendPointData,
    MockInterviewCourseStatsWeakestData,
    RecomputeUserMockInterviewCourseStatsParams,
    UserMockInterviewCourseStatsParams,
    UserMockInterviewCourseStatsResult,
} from "./types"

/** How many most-recent completed attempts to scan for the aggregation ΓÇö bounds the aggregation cost. */
const STATS_SCAN_CAP = 50

/** How many of the most recent scanned attempts feed the trend line. */
const STATS_TREND_LENGTH = 10

/** Below this many scanned attempts, every aggregate is noise ΓÇö HONEST gate, mirrors the FE Scorecard/FlashcardStats convention of never showing a stat derived from too small a sample. */
const MIN_ATTEMPTS_FOR_STATS = 3

/** A phase/kind below this fraction of its max is "weak" ΓÇö mirrors `MockInterviewScorecard`'s own `WEAK_PHASE_THRESHOLD`. */
const WEAK_THRESHOLD = 0.6

/** A phase/kind must be weak at least this many times before it is surfaced as THE pattern to fix (not one bad day). */
const WEAK_MIN_COUNT = 3

/** `attributeScores` entries have no `max` field ΓÇö always 0-100 direct, so every fold treats `max` as this fixed constant. */
const ATTRIBUTE_SCORE_MAX = 100

/** The 5 canonical design phase literals ΓÇö `byPhase` only ever aggregates these (a legacy/garbled phase literal is dropped, never silently mixed in). */
const DESIGN_PHASE_KEYS: ReadonlySet<string> = new Set(Object.values(MockInterviewPhase))

/** The 3 canonical seniority-level literals ΓÇö `byLevel` only ever aggregates these (a null/legacy level is dropped, never silently mixed in). */
const VALID_LEVEL_KEYS: ReadonlySet<string> = new Set(Object.values(FlashcardLevel))

/** A `byLanguage` entry needs at least this many scored questions before it's trustworthy enough to compare against another language ΓÇö a language drawn once ever is noise, not a signal. */
const MIN_LANGUAGE_BREAKDOWN_SAMPLE = 2

/** A gap must recur at least this many times across scanned attempts to count as "recurring" (one mention is just one bad session, not a pattern). */
const RECURRING_GAP_MIN_COUNT = 2

/** How many of the most-frequent recurring gaps to surface. */
const RECURRING_GAPS_TOP_N = 5

/** Accumulator for one breakdown key (phase or kind) while scanning attempts. */
interface BreakdownAccumulator {
    scoreSum: number
    maxSum: number
    weakCount: number
    attemptCount: number
    /** Attempt createdAt + matchedContentId candidates, newest-scanned-first, for resolving the weakest entry's deep-link without a second pass. */
    weakMatches: Array<{ createdAt: Date, matchedContentId: string | null }>
}

/** Accumulator for one normalized recurring-gap key while scanning attempts. */
interface RecurringGapAccumulator {
    /** Most-recently-seen original casing (attempts are scanned newest-first) ΓÇö used for display. */
    text: string
    /** How many scanned attempts recorded this (normalized) gap. */
    count: number
}

/** Empty/zeroed result shape for `insufficientData: true`. */
const EMPTY_RESULT: UserMockInterviewCourseStatsResult = {
    insufficientData: true,
    modeSplit: {
        qnaCount: 0,
        designCount: 0,
    },
    trend: [],
    byPhase: [],
    byKind: [],
    byAttribute: [],
    byLevel: [],
    byLanguage: [],
    recurringGaps: [],
    weakest: null,
    verdictCounts: {
        pass: 0,
        borderline: 0,
        fail: 0,
    },
}

@Injectable()
/**
 * CQRS projection service for a user's mock-interview COURSE stats ΓÇö one row
 * per enrollment. The heavy attempts scan + fold (trend / mode split / two
 * breakdown axes / weakest) runs ONLY in {@link recompute} (the projector,
 * triggered by CDC on `mock_interview_attempts`), building the aggregate
 * jsonb. {@link getStats} reads the flat row with a TTL lazy-refresh ΓÇö no
 * per-request scan/fold.
 *
 * This mirrors what `MyMockInterviewStatsService.compute` used to do inline
 * on every read (a bounded Γëñ50-row scan) ΓÇö a violation of
 * `.claude/be/rules/cqrs-no-inline-aggregate.md` ("kß╗â cß║ú scale nhß╗Å").
 */
export class UserMockInterviewCourseStatsProjectionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
    ) {}

    /**
     * Recompute + upsert the mock-interview-course-stats aggregate for one
     * enrollment (idempotent).
     *
     * @param params - {@link RecomputeUserMockInterviewCourseStatsParams}
     */
    async recompute(
        {
            enrollmentId,
            entityManager,
        }: RecomputeUserMockInterviewCourseStatsParams,
    ): Promise<void> {
        // honour the caller's transaction when given, else the service connection
        const manager = entityManager ?? this.entityManager

        const value = await this.computeAggregate(manager,
            enrollmentId)

        await manager.query(
            `INSERT INTO user_mock_interview_course_stats_projections (enrollment_id, value)
             VALUES ($1::uuid, $2::jsonb)
             ON CONFLICT (enrollment_id) DO UPDATE SET
                 value      = EXCLUDED.value,
                 updated_at = now()`,
            [
                enrollmentId,
                JSON.stringify(value),
            ],
        )
    }

    /**
     * Read an enrollment's mock-interview-course stats, TTL lazy-refreshed.
     *
     * @param params - {@link UserMockInterviewCourseStatsParams}
     * @returns the stats (the `insufficientData: true` empty shape when the enrollment has no history / row).
     */
    async getStats(
        {
            enrollmentId,
        }: UserMockInterviewCourseStatsParams,
    ): Promise<UserMockInterviewCourseStatsResult> {
        let row = await this.entityManager.findOne(
            UserMockInterviewCourseStatsProjectionEntity,
            {
                where: {
                    enrollmentId,
                },
            },
        )
        // missing / past freshness window ΓåÆ recompute + re-read
        if (!row || this.isStale(row.updatedAt)) {
            await this.recompute({
                enrollmentId,
            })
            row = await this.entityManager.findOne(
                UserMockInterviewCourseStatsProjectionEntity,
                {
                    where: {
                        enrollmentId,
                    },
                },
            )
        }
        const value = row?.value as Partial<UserMockInterviewCourseStatsResult> | undefined
        if (!value || Object.keys(value).length === 0) {
            return EMPTY_RESULT
        }
        return {
            insufficientData: value.insufficientData ?? true,
            modeSplit: value.modeSplit ?? EMPTY_RESULT.modeSplit,
            trend: value.trend ?? [],
            byPhase: value.byPhase ?? [],
            byKind: value.byKind ?? [],
            byAttribute: value.byAttribute ?? [],
            byLevel: value.byLevel ?? [],
            byLanguage: value.byLanguage ?? [],
            recurringGaps: value.recurringGaps ?? [],
            weakest: value.weakest ?? null,
            verdictCounts: value.verdictCounts ?? EMPTY_RESULT.verdictCounts,
        }
    }

    /**
     * The full aggregate ΓÇö trend / mode split / both breakdown axes /
     * weakest ΓÇö COPIED verbatim (parameterized by `enrollmentId`) from
     * `MyMockInterviewStatsService.compute`.
     */
    private async computeAggregate(
        manager: EntityManager,
        enrollmentId: string,
    ): Promise<UserMockInterviewCourseStatsResult> {
        // attempts are keyed by enrollment directly (no user/course join needed)
        const attempts = await manager.find(
            MockInterviewAttemptEntity,
            {
                where: {
                    enrollment: {
                        id: enrollmentId,
                    },
                },
                order: {
                    createdAt: "DESC",
                },
                take: STATS_SCAN_CAP,
            },
        )

        if (attempts.length < MIN_ATTEMPTS_FOR_STATS) {
            return EMPTY_RESULT
        }

        // `byLanguage` needs each qna attempt's DRAWN session (the language
        // lives on `seedQuestions[i].givenCodes`, not on the attempt itself)
        // ΓÇö batch-fetch once instead of a per-attempt N+1 lookup.
        const qnaSessionIds = [...new Set(
            attempts
                .filter((attempt) => attempt.mode === "qna")
                .map((attempt) => attempt.sessionId),
        )]
        const sessions = qnaSessionIds.length > 0
            ? await manager.find(
                MockInterviewSessionEntity,
                {
                    where: {
                        id: In(qnaSessionIds),
                    },
                },
            )
            : []
        const sessionById = new Map(sessions.map((session) => [
            session.id,
            session,
        ]))

        // `attempts` is newest-first (DESC); reverse to oldest-first, then take
        // the last N of that ascending list ΓÇö i.e. the most recent N attempts,
        // oldest-of-those-first, which is what a left-to-right trend line wants
        const trend: Array<MockInterviewCourseStatsTrendPointData> = [...attempts]
            .reverse()
            .slice(-STATS_TREND_LENGTH)
            .map((attempt) => ({
                completedAt: attempt.createdAt,
                overallScore: attempt.overallScore,
                // a null-mode legacy attempt predates the "mode split" ΓÇö the only
                // mode that could have existed then was design
                mode: attempt.mode ?? "design",
                verdict: attempt.verdict,
            }))

        let qnaCount = 0
        let designCount = 0
        const phaseAcc = new Map<string, BreakdownAccumulator>()
        const kindAcc = new Map<string, BreakdownAccumulator>()
        const attributeAcc = new Map<string, BreakdownAccumulator>()
        const levelAcc = new Map<string, BreakdownAccumulator>()
        const languageAcc = new Map<string, BreakdownAccumulator>()
        const gapTally = new Map<string, RecurringGapAccumulator>()
        const verdictCounts = {
            pass: 0,
            borderline: 0,
            fail: 0,
        }

        for (const attempt of attempts) {
            const isQna = attempt.mode === "qna"
            if (isQna) {
                qnaCount += 1
                this.accumulateQuestionReviews(
                    attempt.questionReviews,
                    attempt.createdAt,
                    kindAcc,
                )
                this.accumulateQuestionReviewsByLanguage(
                    attempt.questionReviews,
                    sessionById.get(attempt.sessionId),
                    attempt.createdAt,
                    languageAcc,
                )
            } else {
                designCount += 1
                this.accumulatePhaseScores(
                    attempt.phaseScores,
                    attempt.createdAt,
                    attempt.matchedContentIds,
                    phaseAcc,
                )
            }
            // attributeScores/level are graded on EVERY attempt regardless of
            // mode (not gated by isQna like phase/kind are)
            this.accumulateAttributeScores(
                attempt.attributeScores,
                attempt.createdAt,
                attempt.matchedContentIds,
                attributeAcc,
            )
            this.accumulateLevel(
                attempt.level,
                attempt.overallScore,
                attempt.createdAt,
                attempt.matchedContentIds,
                levelAcc,
            )
            this.accumulateGaps(
                attempt.gaps,
                gapTally,
            )
            if (attempt.verdict === "pass" || attempt.verdict === "borderline" || attempt.verdict === "fail") {
                verdictCounts[attempt.verdict] += 1
            }
        }

        const byPhase = this.finalizeBreakdown(phaseAcc)
        const byKind = this.finalizeBreakdown(kindAcc)
        const byAttribute = this.finalizeBreakdown(attributeAcc)
        const byLevel = this.finalizeBreakdown(levelAcc)
        const byLanguage = this.finalizeBreakdown(languageAcc)
            .filter((item) => item.attemptCount >= MIN_LANGUAGE_BREAKDOWN_SAMPLE)
        const recurringGaps = this.finalizeRecurringGaps(gapTally)
        const weakest = this.resolveWeakest(byPhase,
            phaseAcc,
            byKind,
            kindAcc,
            byAttribute,
            attributeAcc)

        return {
            insufficientData: false,
            modeSplit: {
                qnaCount,
                designCount,
            },
            trend,
            byPhase,
            byKind,
            byAttribute,
            byLevel,
            byLanguage,
            recurringGaps,
            weakest,
            verdictCounts,
        }
    }

    /**
     * Fold one `mode="design"` attempt's `phaseScores[]` into the per-phase
     * accumulator ΓÇö only entries whose `phase` is one of the 5 canonical
     * design phases are counted (a garbled/legacy literal is dropped, never
     * silently mixed in). The attempt's OWN `matchedContentIds[0]` is
     * recorded as this phase's deep-link candidate for THIS attempt when the
     * phase came in weak, so the weakest-entry resolver can pick the most
     * recent one without a second database pass.
     */
    private accumulatePhaseScores(
        phaseScores: unknown,
        createdAt: Date,
        matchedContentIds: Array<string>,
        acc: Map<string, BreakdownAccumulator>,
    ): void {
        for (const entry of toUnknownRecordArray(phaseScores)) {
            const phase = typeof entry.phase === "string" ? entry.phase : ""
            if (!DESIGN_PHASE_KEYS.has(phase)) {
                continue
            }
            const score = typeof entry.score === "number" ? entry.score : 0
            const max = typeof entry.max === "number" && entry.max > 0 ? entry.max : 0
            if (max <= 0) {
                continue
            }
            this.fold(acc,
                phase,
                score,
                max,
                createdAt,
                matchedContentIds[0] ?? null)
        }
    }

    /**
     * Fold one `mode="qna"` attempt's `questionReviews[]` into the per-kind
     * accumulator ΓÇö grouped by `kind` (theory/reasoning/scenario), each
     * entry's OWN `matchedContentId` recorded as this kind's deep-link
     * candidate for THIS attempt when the question came in weak.
     */
    private accumulateQuestionReviews(
        questionReviews: unknown,
        createdAt: Date,
        acc: Map<string, BreakdownAccumulator>,
    ): void {
        for (const entry of toUnknownRecordArray(questionReviews)) {
            const kind = typeof entry.kind === "string" ? entry.kind : ""
            if (kind.length === 0) {
                continue
            }
            const score = typeof entry.score === "number" ? entry.score : 0
            const max = typeof entry.max === "number" && entry.max > 0 ? entry.max : 0
            if (max <= 0) {
                continue
            }
            const matchedContentId = typeof entry.matchedContentId === "string" ? entry.matchedContentId : null
            this.fold(acc,
                kind,
                score,
                max,
                createdAt,
                matchedContentId)
        }
    }

    /**
     * Fold one `mode="qna"` attempt's `questionReviews[]` into the per-language
     * accumulator ΓÇö the language a question was drawn in lives on the SESSION
     * (`seedQuestions[questionIndex].givenCodes[0].lang`), not on the attempt,
     * so this joins each review to its drawn session (batch-fetched by the
     * caller) by `questionIndex`. Only CODE questions (a non-empty
     * `givenCodes`) carry a language ΓÇö a theory/reasoning question with no
     * given code is skipped, never defaulted into a fake "no language"
     * bucket. Missing session (drawn before session rows existed, or
     * resolved as undefined) skips the whole attempt's reviews.
     */
    private accumulateQuestionReviewsByLanguage(
        questionReviews: unknown,
        session: MockInterviewSessionEntity | undefined,
        createdAt: Date,
        acc: Map<string, BreakdownAccumulator>,
    ): void {
        if (!session || !session.seedQuestions) {
            return
        }
        for (const entry of toUnknownRecordArray(questionReviews)) {
            const questionIndex = typeof entry.questionIndex === "number" ? entry.questionIndex : -1
            const seed = questionIndex >= 0 ? session.seedQuestions[questionIndex] : undefined
            const lang = seed?.givenCodes?.[0]?.lang
            if (!seed || !lang) {
                continue
            }
            const score = typeof entry.score === "number" ? entry.score : 0
            const max = typeof entry.max === "number" && entry.max > 0 ? entry.max : 0
            if (max <= 0) {
                continue
            }
            const matchedContentId = typeof entry.matchedContentId === "string" ? entry.matchedContentId : null
            this.fold(acc,
                lang,
                score,
                max,
                createdAt,
                matchedContentId)
        }
    }

    /**
     * Fold one attempt's `attributeScores[]` into the per-attribute
     * accumulator ΓÇö reads EVERY attempt regardless of mode (unlike
     * `accumulatePhaseScores`/`accumulateQuestionReviews`, which are gated by
     * `isQna`). `max` has no persisted field on this entry (confirmed against
     * `grade-mock-interview-session-prompt.service.ts` ΓÇö the score is always
     * 0-100 direct), so it is fixed at {@link ATTRIBUTE_SCORE_MAX} for every
     * entry. The attempt's own `matchedContentIds[0]` is recorded as this
     * attribute's deep-link candidate for THIS attempt when it came in weak,
     * same as `accumulatePhaseScores` does.
     */
    private accumulateAttributeScores(
        attributeScores: unknown,
        createdAt: Date,
        matchedContentIds: Array<string>,
        acc: Map<string, BreakdownAccumulator>,
    ): void {
        for (const entry of toUnknownRecordArray(attributeScores)) {
            const key = typeof entry.key === "string" ? entry.key : ""
            if (key.length === 0) {
                continue
            }
            const score = typeof entry.score === "number" ? entry.score : 0
            this.fold(acc,
                key,
                score,
                ATTRIBUTE_SCORE_MAX,
                createdAt,
                matchedContentIds[0] ?? null)
        }
    }

    /**
     * Fold one attempt's `overallScore` into its seniority-level accumulator ΓÇö
     * reads EVERY attempt regardless of mode, same as
     * {@link accumulateAttributeScores}. A null/legacy level (not one of the 3
     * canonical {@link VALID_LEVEL_KEYS}) is dropped rather than mixed into a
     * fake "any level" bucket.
     */
    private accumulateLevel(
        level: string | null,
        overallScore: number,
        createdAt: Date,
        matchedContentIds: Array<string>,
        acc: Map<string, BreakdownAccumulator>,
    ): void {
        if (!level || !VALID_LEVEL_KEYS.has(level)) {
            return
        }
        this.fold(acc,
            level,
            overallScore,
            ATTRIBUTE_SCORE_MAX,
            createdAt,
            matchedContentIds[0] ?? null)
    }

    /**
     * Tally one attempt's `gaps[]` into the recurring-gap map ΓÇö each entry is
     * trimmed+lowercased to a dedupe key (so "Trade-off" and "trade-off "
     * count as the same recurring gap), while the map keeps the
     * MOST-RECENTLY-SEEN original casing for display (attempts are scanned
     * newest-first).
     */
    private accumulateGaps(
        gaps: Array<string> | null | undefined,
        tally: Map<string, RecurringGapAccumulator>,
    ): void {
        for (const raw of gaps ?? []) {
            if (typeof raw !== "string") {
                continue
            }
            const text = raw.trim()
            if (text.length === 0) {
                continue
            }
            const key = text.toLowerCase()
            const existing = tally.get(key)
            if (existing) {
                existing.count += 1
            } else {
                tally.set(
                    key,
                    {
                        text,
                        count: 1,
                    },
                )
            }
        }
    }

    /** Turn the recurring-gap tally into the top-N, most-frequent-first array the response returns ΓÇö gaps seen fewer than {@link RECURRING_GAP_MIN_COUNT} times don't qualify (one mention is one bad session, not a pattern). */
    private finalizeRecurringGaps(
        tally: Map<string, RecurringGapAccumulator>,
    ): Array<MockInterviewCourseStatsRecurringGapData> {
        return [...tally.values()]
            .filter((entry) => entry.count >= RECURRING_GAP_MIN_COUNT)
            .sort((left, right) => right.count - left.count)
            .slice(0,
                RECURRING_GAPS_TOP_N)
            .map((entry) => ({
                text: entry.text,
                count: entry.count,
            }))
    }

    /** Fold one (score, max) observation for `key` into its accumulator, tracking a deep-link candidate when it's weak. */
    private fold(
        acc: Map<string, BreakdownAccumulator>,
        key: string,
        score: number,
        max: number,
        createdAt: Date,
        matchedContentId: string | null,
    ): void {
        const existing = acc.get(key) ?? {
            scoreSum: 0,
            maxSum: 0,
            weakCount: 0,
            attemptCount: 0,
            weakMatches: [],
        }
        existing.scoreSum += score
        existing.maxSum += max
        existing.attemptCount += 1
        if (score / max < WEAK_THRESHOLD) {
            existing.weakCount += 1
            existing.weakMatches.push({
                createdAt,
                matchedContentId,
            })
        }
        acc.set(key,
            existing)
    }

    /** Turn an accumulator map into the sorted (weakest-first) breakdown array the response returns. */
    private finalizeBreakdown(
        acc: Map<string, BreakdownAccumulator>,
    ): Array<MockInterviewCourseStatsBreakdownItemData> {
        return [...acc.entries()]
            .map(([key,
                entry]) => ({
                key,
                avgScore: entry.attemptCount > 0 ? entry.scoreSum / entry.attemptCount : 0,
                avgMax: entry.attemptCount > 0 ? entry.maxSum / entry.attemptCount : 0,
                weakCount: entry.weakCount,
                attemptCount: entry.attemptCount,
            }))
            .sort((left, right) => (left.avgScore / (left.avgMax || 1)) - (right.avgScore / (right.avgMax || 1)))
    }

    /**
     * Pick the single weakest entry across BOTH axes (lowest score/max ratio
     * AND weak often enough to be a real pattern ΓÇö `weakCount >=
     * WEAK_MIN_COUNT`, not one bad day), resolving its deep-link from the
     * MOST RECENT attempt where it came in weak.
     */
    private resolveWeakest(
        byPhase: Array<MockInterviewCourseStatsBreakdownItemData>,
        phaseAcc: Map<string, BreakdownAccumulator>,
        byKind: Array<MockInterviewCourseStatsBreakdownItemData>,
        kindAcc: Map<string, BreakdownAccumulator>,
        byAttribute: Array<MockInterviewCourseStatsBreakdownItemData>,
        attributeAcc: Map<string, BreakdownAccumulator>,
    ): MockInterviewCourseStatsWeakestData | null {
        const candidates: Array<{ item: MockInterviewCourseStatsBreakdownItemData, axis: "phase" | "kind" | "attribute", acc: Map<string, BreakdownAccumulator> }> = [
            ...byPhase.map((item) => ({
                item, axis: "phase" as const, acc: phaseAcc
            })),
            ...byKind.map((item) => ({
                item, axis: "kind" as const, acc: kindAcc
            })),
            ...byAttribute.map((item) => ({
                item, axis: "attribute" as const, acc: attributeAcc
            })),
        ].filter((candidate) => candidate.item.weakCount >= WEAK_MIN_COUNT)

        if (candidates.length === 0) {
            return null
        }

        const weakest = candidates.sort(
            (left, right) => (left.item.avgScore / (left.item.avgMax || 1)) - (right.item.avgScore / (right.item.avgMax || 1)),
        )[0]

        const weakMatches = weakest.acc.get(weakest.item.key)?.weakMatches ?? []
        const mostRecent = [...weakMatches].sort(
            (left, right) => right.createdAt.getTime() - left.createdAt.getTime(),
        )[0]

        return {
            key: weakest.item.key,
            axis: weakest.axis,
            avgScore: weakest.item.avgScore,
            avgMax: weakest.item.avgMax,
            weakCount: weakest.item.weakCount,
            matchedContentId: mostRecent?.matchedContentId ?? null,
        }
    }

    /**
     * Whether a projection row is past its freshness window.
     *
     * @param updatedAt - the row's last write time.
     * @returns true when older than the configured TTL.
     */
    private isStale(updatedAt: Date): boolean {
        return Date.now() - updatedAt.getTime() > envConfig().projection.staleAfterMs
    }
}

